      "path": "dsh/scripts/build.mjs",
      "content": "#!/usr/bin/env node\n// Build the plugin's bundled ThoughtDAG SPA with a subpath base so the host\n// half can serve it under /thoughtdag/. Usage:\n//   node scripts/build.mjs [thoughtdag-repo] [outDir]   (from dsh/: node scripts/build.mjs ..)\n//   npm run dsh:build                                  (from the repo root)\nimport { execFileSync } from 'node:child_process'\nimport { createRequire } from 'node:module'\nimport { mkdirSync, rmSync, cpSync, existsSync } from 'node:fs'\nimport { resolve, dirname } from 'node:path'\nimport { fileURLToPath } from 'node:url'\n\nconst __dirname = dirname(fileURLToPath(import.meta.url))\nconst repo = resolve(process.argv[2] ?? process.env.THOUGHTDAG_REPO ?? resolve(__dirname, '../..'))\nconst outDir = resolve(process.argv[3] ?? resolve(__dirname, '../dist-app'))\nconst tmp = resolve(__dirname, '../.dist-tmp')\n\nif (!existsSync(resolve(repo, 'package.json'))) {\n  console.error('thoughtdag repo not found at', repo)\n  process.exit(1)\n}\nconsole.log('building thoughtdag (base /thoughtdag/) from', repo)\nrmSync(tmp, { recursive: true, force: true })\n// VITE_API_BASE points the SPA's own proxy calls (/api/models, /api/stream…) at\n// this host, which answers them on the harness's providers.\n// VITE_DSH_BRIDGE tells the SPA where the plugin's session bridge answers, so\n// it installs the harness-backed window.desktopSessions at boot\n// The type gate the root `npm run build` has, then vite itself. tsc and vite\n// ship pure-JS entries no installer ever touches, so both run as node scripts\n// through this process's own node binary: execFileSync cannot spawn `npm` (a\n// .cmd needing a shell on Windows) nor the extensionless .bin shims, while a\n// JS entry takes argv verbatim — no shell, no quoting, one code path.\nexecFileSync(process.execPath, [resolve(repo, 'node_modules/typescript/bin/tsc'), '-b'], { cwd: repo, stdio: 'inherit' })\nexecFileSync(process.execPath, [resolve(repo, 'node_modules/vite/bin/vite.js'), 'build', '--base=/thoughtdag/', '--outDir=' + tmp], { cwd: repo, stdio: 'inherit', env: { ...process.env, VITE_DSH_BRIDGE: '/thoughtdag/api', VITE_API_BASE: '/thoughtdag' } })\n// keep only what the embedded SPA needs; landing-page covers are not served\nrmSync(resolve(tmp, 'covers'), { recursive: true, force: true })\n// the tutorial's gifs stay: a first-time visitor inside the harness sees the same walkthrough\nrmSync(outDir, { recursive: true, force: true })\nmkdirSync(outDir, { recursive: true })\ncpSync(tmp, outDir, { recursive: true })\nrmSync(tmp, { recursive: true, force: true })\nconsole.log('plugin SPA written to', outDir)\n\n// The why layer: the CLI's library, bundled for the host (Node), so the plugin\n// registers the same four questions as native harness tools and a /why command\n// esbuild is the one tool that cannot run as a node script: its installer\n// overwrites bin/esbuild with the native binary on macOS and Linux (the JS\n// shim survives only on Windows), so node on it dies with a SyntaxError. Its\n// JS API locates the platform binary itself — the same flags as the root\n// `cli:build`, resolved from the repo's own esbuild, still no shell anywhere.\nconst whyOut = resolve(__dirname, '../lib/why.mjs')\nawait createRequire(resolve(repo, 'package.json'))('esbuild').build({\n  entryPoints: [resolve(repo, 'cli/src/lib.ts')],\n  bundle: true,\n  platform: 'node',\n  format: 'esm',\n  target: 'node22',\n  define: { 'import.meta.env': '{}' },\n  outfile: whyOut,\n  logLevel: 'warning',\n})\nconsole.log('why layer written to', whyOut)\n\n// The shared agent runtime (plain Node): the host serves it over HTTP so the\n// canvas inside the harness runs agents exactly as the desktop shell does\nconst runtimeOut = resolve(__dirname, '../lib/runtime')\nrmSync(runtimeOut, { recursive: true, force: true })\ncpSync(resolve(repo, 'runtime'), runtimeOut, { recursive: true })\nconsole.log('agent runtime written to', runtimeOut)\n"
    },
    {
      "path": "runtime/backup-write.cjs",
      "content": "// The canvas's local backup, written by the HOST (#66).\n//\n// The File System Access API needs a directory handle, and Chromium's own\n// picker never returns inside the harness frame on Windows — the canvas cannot\n// write the file itself there. So the canvas keeps the absolute path the\n// harness's own picker handed it and asks the host to write instead.\n//\n// This lives beside the agent runtimes rather than inline in the plugin, so the\n// path rules can be tested without a harness: scripts/test-backup-write.mjs.\n// Pure Node, no harness context.\n'use strict';\nconst { mkdir, writeFile } = require('node:fs/promises');\nconst { dirname, isAbsolute, resolve, sep } = require('node:path');\n\n/** An error the endpoint should report as 400 rather than 500. */\nclass BackupRequestError extends Error {}\n\n/**\n * Write one canvas backup under `dir`.\n *\n * @param {{ dir: unknown, name: unknown, json: unknown }} body the request body\n * @returns {Promise<string>} the absolute file written\n * @throws {BackupRequestError} when the request itself is not writable\n */\nasync function writeBackup(body) {\n  const dir = typeof body?.dir === 'string' ? body.dir : '';\n  const name = typeof body?.name === 'string' ? body.name : '';\n  const json = typeof body?.json === 'string' ? body.json : null;\n  // an absolute path is the whole safety property: a relative one would resolve\n  // against the plugin's cwd, which the canvas cannot know.\n  // isAbsolute, NOT resolve(dir).startsWith(sep) — on Windows a drive path\n  // starts with \"C:\" and would never match the separator, so that test refuses\n  // every real request there while passing on POSIX.\n  if (!dir || !isAbsolute(dir) || !name || json === null) {\n    throw new BackupRequestError('dir must be an absolute path; name and json are required');\n  }\n  // `name` is a RELATIVE path the canvas chose (native canvases at the folder\n  // root, session mirrors under cli/), so it is sanitized segment by segment\n  const parts = name.replace(/\\\\/g, '/').split('/').filter((p) => p && p !== '.' && p !== '..');\n  if (parts.length === 0) throw new BackupRequestError('name must have at least one path segment');\n  const last = parts[parts.length - 1].replace(/[<>:\"|?*\\u0000-\\u001f]/g, '_').slice(0, 120);\n  if (!last) throw new BackupRequestError('name resolves to an empty file name');\n  const target = resolve(dir, ...parts.slice(0, -1), last);\n  // Belt and braces, and it has to agree with the gate above: compare against\n  // resolve(dir) — NOT resolve(dir) + sep, which would reject a Windows path\n  // for the same reason the startsWith(sep) test did.\n  const inside = resolve(dir);\n  if (target !== inside && !target.startsWith(inside.endsWith(sep) ? inside : inside + sep)) {\n    throw new BackupRequestError('name escapes the backup directory');\n  }\n  await mkdir(dirname(target), { recursive: true });\n  await writeFile(target, json, 'utf8');\n  return target;\n}\n\nmodule.exports = { writeBackup, BackupRequestError };\n"
    },
    {
      "path": "cli/src/lib.ts",
      "content": "// The why layer as a library: the stores under ~/.thoughtdag, the index over\n// every runner's session files, and the four questions (why_check, why_file,\n// find, recall_turn) as functions that return text. `main.ts` is the command\n// line and the MCP server over this; the DeepSeek Harness plugin bundles it\n// and registers the same four questions as native harness tools.\n// thoughtdag — the why layer's command line.\n//\n//   thoughtdag index [--full]          build or refresh the footprint index\n//   thoughtdag why <path> [--include-read] [--all] [--limit N] [--json]\n//   thoughtdag recall <session> <n>    one turn in full\n//   thoughtdag status                  what the index holds, and how much of it is evidence\n//   thoughtdag purge                   delete everything this tool stored\n//\n// Facts come straight off tool calls in the local session files, never\n// from free text or a model. Three stores, three kinds of content:\n//   fact-index.json           observed events + verbatim excerpts + pointers\n//   interpretation-cache.json heuristics read off the answers (deletable)\n//   text-index.jsonl          what was asked, answered and attached, verbatim, one\n//                             turn per line — streamed, never parsed whole — for exact\n//                             phrase search (deletable, rebuilt on index); text-index.json\n//                             is its small manifest (which sources are in it)\n// Since 0.4.21 the index also holds what two agents wrote down for\n// themselves between sessions — Claude Code's per-project memory directory\n// and Codex's memories — as sessions of kind 'memory': a file is a session,\n// each entry a turn (its heading asked, its body answered), so find and\n// recall answer over them unchanged and a canvas can cite one entry.\n// Source files are read, never written. The index is derived and can\n// always be rebuilt; a query refreshes it first when a source moved on.\n\nimport { promises as fsp, createReadStream, createWriteStream } from 'node:fs';\nimport { createInterface } from 'node:readline';\nimport path from 'node:path';\nimport os from 'node:os';\nimport * as zlib from 'node:zlib';\nimport { createHash } from 'node:crypto';\nimport { ClaudeSessionCollector } from '../../src/lib/adapters/claude-code-session';\nimport { CodexSessionCollector } from '../../src/lib/adapters/codex-session';\nimport { DshSessionCollector } from '../../src/lib/adapters/dsh-session';\nimport { PiSessionCollector } from '../../src/lib/adapters/pi-session';\nimport { decompressZstdFrames } from '../../src/lib/adapters/dsh-zstd';\nimport { conclusionOf } from '../../src/lib/turn-insight';\nimport type { RunnerTurn } from '../../src/lib/adapters/shared';\nimport { sessionToEvents, deriveTouches, absolutePath, fileUri, filePathOf, urlArtifact, arxivArtifact, type ProjectableSession } from '../../src/lib/events/project';\nimport type { Locator } from '../../src/lib/events/types';\nimport { MANIFESTS } from '../../src/lib/events/manifests';\nimport { canvasToEvents, isCanvasBackup } from '../../src/lib/adapters/thoughtdag-canvas';\nimport type { CanonicalEvent } from '../../src/lib/events/types';\n\n// ─── records ─────────────────────────────────────────────────────────\n\ntype Op = 'read' | 'fetch' | 'attach' | 'write' | 'edit';\nconst readLike = (op: Op): boolean => op === 'read' || op === 'fetch' || op === 'attach';\n/** observed: the op, and the first differing line of the change (verbatim, partial) */\ninterface Touch { op: Op; d?: string; l?: Locator[] }\n/** `cwd`: a memory entry naming the project it is about (Codex's task groups do); a session's turns inherit the session's */\ninterface FactTurn { i: number; t: string; item?: string; at?: string; q: string; ops: Record<string, Touch>; cwd?: string }\n/** One SOURCE FILE's worth of facts. A logical session (`id`) can span\n *  several — a resumed Codex thread opens a new rollout each time — so\n *  the store is keyed by source, and readers group by `id`. */\ninterface FactSession {\n  id: string; runner: 'claude-code' | 'codex' | 'dsh' | 'pi' | 'thoughtdag'; file: string; mtime: number; size: number;\n  cwd: string; workspace: string; title: string; subagent?: boolean; turns: FactTurn[];\n  /** a memory file (Claude Code's memory directory, Codex's memories), not a conversation */\n  kind?: 'memory';\n  /** opened from a canvas hand-off */\n  anchor?: { project: string; node: string; bundle: string };\n}\ninterface FactIndex {\n  version: number; builtAt: string;\n  /** keyed by canonical source file path */\n  sessions: Record<string, FactSession>;\n  /** display names for artifacts that are not files (a canvas attachment's file name) */\n  names: Record<string, string>;\n  /** bundles a canvas handed off (a `bundle` commit), by bundle id: what an anchor is checked against */\n  bundles: Record<string, { canvas: string; node: string }>;\n  /** .jsonl files seen that are not sessions, with the stat they had —\n      remembered so a stray file does not make every query refresh */\n  skipped: Record<string, { mtime: number; size: number }>;\n}\n/** heuristics: the answer's closing paragraph, the earlier ask a bare \"ok\"\n *  answers, the paragraph naming each file — candidates, not facts */\ninterface CacheTurn { c?: string; p?: string; m?: Record<string, string> }\ninterface CacheIndex { version: number; sessions: Record<string, Record<string, CacheTurn>> }\n/** verbatim text per turn: q = what was asked, a = what was answered, m = what the\n *  node's materials say (extracted text, head only). Search runs over this. */\ninterface TextTurn { q: string; a: string; m?: string }\n/** manifest of the text lines: source key → number of turns present */\ninterface TextIndex { version: number; sessions: Record<string, number> }\ninterface TextLine extends TextTurn { k: string; i: number }\n\nconst INDEX_VERSION = 14; // 14: archived canvas nodes leave the record (#51); 13: failed tool calls are no footprints (#50)\nconst EXCERPT = 200;\n\nconst HOME = process.env.THOUGHTDAG_HOME ?? path.join(os.homedir(), '.thoughtdag');\nconst FACT_FILE = path.join(HOME, 'fact-index.json');\nconst CACHE_FILE = path.join(HOME, 'interpretation-cache.json');\nconst TEXT_FILE = path.join(HOME, 'text-index.json');\nconst TEXT_LINES = path.join(HOME, 'text-index.jsonl');\nconst LEGACY_FILE = path.join(HOME, 'why-index.json');\nconst CONFIG_FILE = path.join(HOME, 'config.json');\n// DSH keeps one directory per session under <DSH_HOME>/sessions/<encoded cwd>/\nconst DSH_ROOT = path.join(process.env.DSH_HOME ?? path.join(os.homedir(), '.dsh'), 'sessions');\n// Pi keeps one JSONL per session under ~/.pi/agent/sessions/<encoded cwd>/\nconst PI_ROOT = path.join(os.homedir(), '.pi', 'agent', 'sessions');\nconst ROOTS = (process.env.THOUGHTDAG_SESSION_ROOTS?.split(path.delimiter).filter(Boolean))\n  ?? [path.join(os.homedir(), '.claude', 'projects'), path.join(os.homedir(), '.codex', 'sessions'), DSH_ROOT, PI_ROOT];\n\n// What an agent wrote down for itself between sessions. Claude Code keeps one\n// markdown file per fact under <project>/memory/ (frontmatter names it; the\n// MEMORY.md there is only an index of the others); Codex keeps\n// ~/.codex/memories: MEMORY.md by task group (each naming its cwd),\n// raw_memories.md by thread, memory_summary.md, and ad-hoc extensions.\n// THOUGHTDAG_MEMORY_ROOTS lists them explicitly as runner=path pairs; a test\n// store that names its session roots and no memory roots gets none.\ntype MemoryRunner = 'claude-code' | 'codex';\nconst MEMORY_ROOTS: { runner: MemoryRunner; root: string }[] = (() => {\n  const env = process.env.THOUGHTDAG_MEMORY_ROOTS;\n  if (env !== undefined) {\n    return env.split(path.delimiter).filter(Boolean).flatMap((e) => {\n      const m = /^(claude-code|codex)=(.+)$/.exec(e);\n      return m ? [{ runner: m[1] as MemoryRunner, root: m[2] }] : [];\n    });\n  }\n  if (process.env.THOUGHTDAG_SESSION_ROOTS) return [];\n  return [\n    { runner: 'claude-code', root: path.join(os.homedir(), '.claude', 'projects') },\n    { runner: 'codex', root: path.join(os.homedir(), '.codex', 'memories') },\n  ];\n})();\nconst isMemoryFile = (file: string, runner: MemoryRunner): boolean => {\n  if (!file.endsWith('.md')) return false;\n  if (runner === 'claude-code') return path.basename(path.dirname(file)) === 'memory' && path.basename(file) !== 'MEMORY.md';\n  return true;\n};\n\n/** Folders holding canvases (*.thoughtdag.json). Always: the records the\n *  desktop app writes itself under <home>/canvases. Plus the env var, or\n *  what `index --canvas <dir>` remembered — backup folders, for canvases\n *  that live on another machine or were deleted from the app. The same\n *  project in two files collapses to one session. */\nconst CANVAS_RECORDS = path.join(HOME, 'canvases');\nasync function canvasRoots(): Promise<string[]> {\n  const env = process.env.THOUGHTDAG_CANVAS_ROOTS?.split(path.delimiter).filter(Boolean);\n  if (env) return [CANVAS_RECORDS, ...env];\n  try { const c = JSON.parse(await fsp.readFile(CONFIG_FILE, 'utf8')) as { canvasRoots?: string[] }; return [CANVAS_RECORDS, ...(c.canvasRoots ?? [])]; } catch { return [CANVAS_RECORDS]; }\n}\nasync function rememberCanvasRoot(dir: string): Promise<void> {\n  const roots = await canvasRoots();\n  const abs = path.resolve(dir);\n  if (!roots.includes(abs)) await writePrivate(CONFIG_FILE, { canvasRoots: [...roots, abs] });\n}\n\n// ─── files ───────────────────────────────────────────────────────────\n\ninterface FileStat { file: string; mtime: number; size: number; /** set when the file is a memory file, and whose */ memory?: MemoryRunner }\n\nconst isCanvasFile = (name: string): boolean => /\\.thoughtdag\\.json$/i.test(name);\n// a runner's log: JSONL, or DSH's zstd-framed JSONL\nconst isSessionFile = (name: string): boolean => name.endsWith('.jsonl') || name.endsWith('.jsonl.zstd');\n\nasync function walk(dir: string, depth: number, out: FileStat[], accept: (name: string) => boolean): Promise<void> {\n  if (depth > 5) return;\n  let entries;\n  try { entries = await fsp.readdir(dir, { withFileTypes: true }); } catch { return; }\n  for (const ent of entries) {\n    const p = path.join(dir, ent.name);\n    if (ent.isDirectory()) await walk(p, depth + 1, out, accept);\n    else if (ent.isFile() && accept(ent.name)) {\n      try { const st = await fsp.stat(p); out.push({ file: p, mtime: st.mtimeMs, size: st.size }); } catch { /* raced */ }\n    }\n  }\n}\n\nasync function listSources(): Promise<FileStat[]> {\n  const files: FileStat[] = [];\n  for (const root of ROOTS) await walk(root, 0, files, isSessionFile);\n  for (const root of await canvasRoots()) await walk(root, 0, files, isCanvasFile);\n  for (const { runner, root } of MEMORY_ROOTS) {\n    const md: FileStat[] = [];\n    await walk(root, 0, md, (name) => name.endsWith('.md'));\n    for (const m of md) if (isMemoryFile(m.file, runner)) files.push({ ...m, memory: runner });\n  }\n  return files;\n}\n\nasync function firstLine(file: string): Promise<string> {\n  const rl = createInterface({ input: createReadStream(file, { encoding: 'utf8', highWaterMark: 65536 }) });\n  for await (const line of rl) { rl.close(); return line; }\n  return '';\n}\n\nasync function realOr(p: string): Promise<string> { try { return await fsp.realpath(p); } catch { return p; } }\n\n/** One spelling per path, on both sides of a query: the real path when\n *  it exists, else the real path of its nearest existing ancestor plus\n *  the rest (macOS /var → /private/var, symlinked checkouts). Runners\n *  write paths as they saw them; the index keys them canonically. */\nasync function canonicalPath(p: string, memo?: Map<string, string>): Promise<string> {\n  const hit = memo?.get(p);\n  if (hit) return hit;\n  let out: string;\n  try { out = await fsp.realpath(p); } catch {\n    const parent = path.dirname(p);\n    out = parent === p ? p : path.join(await canonicalPath(parent, memo), path.basename(p));\n  }\n  memo?.set(p, out);\n  return out;\n}\n\n/** The workspace a directory belongs to: its git root, else the directory\n *  itself. Sessions started from a subfolder of one repo share a workspace. */\nasync function workspaceOf(dir: string): Promise<string> {\n  let cur = await realOr(dir);\n  for (;;) {\n    try { await fsp.stat(path.join(cur, '.git')); return cur; } catch { /* keep climbing */ }\n    const up = path.dirname(cur);\n    if (up === cur) return await realOr(dir);\n    cur = up;\n  }\n}\n\n// ─── parsing ─────────────────────────────────────────────────────────\n\nconst strongest = (a: Op | undefined, b: Op): Op => (a === 'edit' || a === 'write') ? a : b;\n\n/** An artifact id with its real filesystem spelling: file:// ids go through\n *  realpath (symlinks, /var → /private/var); web and paper ids are already\n *  canonical. */\nasync function canonicalArtifact(id: string, memo: Map<string, string>): Promise<string> {\n  const p = filePathOf(id);\n  return p ? fileUri(await canonicalPath(p, memo)) : id;\n}\n\n/** The name a paragraph would use for this artifact. */\nfunction mentionKey(id: string): string {\n  const p = filePathOf(id);\n  if (p) return path.basename(p);\n  if (id.startsWith('arxiv:')) return id.slice('arxiv:'.length);\n  try { const u = new URL(id); return u.pathname.split('/').filter(Boolean).pop() ?? u.hostname; } catch { return id; }\n}\n\n/** How a person reads an artifact id: a path relative to here, a URL, a paper id. */\nasync function displayOf(id: string, names: Record<string, string> = {}): Promise<string> {\n  const p = filePathOf(id);\n  if (!p) return names[id] ? `${names[id]}  (${id})` : id;\n  const rel = path.relative(await realOr(process.cwd()), await realOr(p));\n  return rel.startsWith('..') || path.isAbsolute(rel) ? p : rel;\n}\nconst clipLine = (s: string, max: number): string => { const l = s.trim(); return l.length > max ? `${l.slice(0, max)}…` : l; };\n\n/** The last paragraph of the answer that names the file — a candidate\n *  explanation, not a verified reason. */\nfunction mentionOf(response: string, key: string): string | undefined {\n  const base = key.toLowerCase();\n  if (base.length < 4) return undefined;\n  const paras = response.replace(/```[\\s\\S]*?```/g, '').split(/\\n\\s*\\n/)\n    .map((p) => p.replace(/!?\\[([^\\]]*)\\]\\([^)]*\\)/g, '$1').replace(/[#*`>|_~]/g, '').replace(/\\s+/g, ' ').trim())\n    // a sources list or a lead-in to a block names the file without saying anything about it\n    .filter((p) => p.length > 12 && p.toLowerCase().includes(base) && !/[:：]$/.test(p) && !/^(sources?|references?|来源|参考)\\b/i.test(p));\n  const last = paras[paras.length - 1];\n  return last ? clipLine(last, 240) : undefined;\n}\n\nfunction questionExcerpt(text: string): string {\n  const cmd = text.match(/<command-name>([^<]+)<\\/command-name>/);\n  const line = (cmd ? cmd[1] : text).split('\\n').map((l) => l.trim()).find((l) => l && !l.startsWith('<')) ?? '';\n  return clipLine(line, EXCERPT);\n}\n\n// node:zlib grew zstd in 22.15; on an older Node a DSH log is skipped and\n// `index` says so once, instead of failing the whole build.\nconst zstdInflate = (zlib as unknown as { zstdDecompressSync?: (b: Uint8Array) => Buffer }).zstdDecompressSync;\nconst ZSTD_MAX = 512 * 1024 * 1024;\nlet zstdSkipped = 0;\n\n/** Read one source file through its adapter: a runner's JSONL through\n *  its collector, a canvas backup through the canvas adapter. Both come\n *  back as the same thing — events, plus the full text per turn that the\n *  interpretation cache reads and the fact index never stores. */\ninterface Projected {\n  runner: FactSession['runner'];\n  nativeId: string;\n  title: string;\n  anchor?: FactSession['anchor'];\n  cwd?: string;\n  subagent?: boolean;\n  events: CanonicalEvent[];\n  texts: Map<string, { question: string; response: string; material?: string }>;\n  manifest: (typeof MANIFESTS)[string];\n  /** jsonl only: the collector's turns, for `recall` */\n  turns?: RunnerTurn[];\n}\n\nasync function eventsOf(file: string, sourceId?: string): Promise<Projected | null> {\n  if (isCanvasFile(file)) {\n    let parsed: unknown;\n    try { parsed = JSON.parse(await fsp.readFile(file, 'utf8')); } catch { return null; }\n    if (!isCanvasBackup(parsed)) return null;\n    const c = canvasToEvents(parsed, { file, sourceId });\n    return { runner: 'thoughtdag', nativeId: c.nativeId, title: c.title, events: c.events, texts: c.texts, manifest: MANIFESTS.thoughtdag };\n  }\n  // DSH logs are zstd frames: whole-file decode (the frame walk needs the\n  // container), then the same line-by-line collector as everyone else. The\n  // other runners' plain JSONL streams through unchanged.\n  let meta: { type?: string; id?: unknown; timestamp?: unknown } = {};\n  let lines: Iterable<string> | AsyncIterable<string>;\n  if (file.endsWith('.zstd')) {\n    if (!zstdInflate) { zstdSkipped++; return null; }\n    let raw: Buffer;\n    try { raw = await fsp.readFile(file); } catch { return null; }\n    if (raw.length > ZSTD_MAX) return null;\n    let text: string;\n    try { text = Buffer.from(decompressZstdFrames(raw, zstdInflate)).toString('utf8'); } catch { return null; }\n    const arr = text.split('\\n');\n    try { meta = JSON.parse(arr[0] ?? '') as { type?: string; id?: unknown; timestamp?: unknown }; } catch { /* not json */ }\n    lines = arr;\n  } else {\n    try { meta = JSON.parse(await firstLine(file)) as { type?: string; id?: unknown; timestamp?: unknown }; } catch { /* not json */ }\n    lines = createInterface({ input: createReadStream(file, { encoding: 'utf8', highWaterMark: 1 << 20 }) });\n  }\n  // the runner is read off the first line's own signature, never off the folder\n  // two runners open with `type: \"session\"`: Pi's header carries a string\n  // timestamp, DSH's a numeric createdAt\n  const runner: 'claude-code' | 'codex' | 'dsh' | 'pi' = meta.type === 'session_meta' ? 'codex'\n    : (meta.type === 'session' && typeof meta.id === 'string') ? (typeof meta.timestamp === 'string' ? 'pi' : 'dsh') : 'claude-code';\n  const collector = runner === 'codex' ? new CodexSessionCollector() : runner === 'dsh' ? new DshSessionCollector() : runner === 'pi' ? new PiSessionCollector() : new ClaudeSessionCollector();\n  for await (const line of lines) collector.feedLine(line);\n  const s = collector.finish();\n  if (!s) return null;\n  const subagent = 'subagent' in s ? !!s.subagent : runner === 'claude-code' && /\\/subagents\\//.test(file);\n  const cwd = ('cwd' in s && s.cwd) ? s.cwd : undefined;\n  const session: ProjectableSession = {\n    runner, nativeId: s.sessionId, title: s.title, file, ...(sourceId ? { sourceId } : {}), schema: MANIFESTS[runner].schema,\n    ...(cwd ? { cwd } : {}), ...(subagent ? { subagent } : {}), turns: s.turns,\n  };\n  const events = sessionToEvents(session);\n  const texts = new Map<string, { question: string; response: string; material?: string }>();\n  for (const e of events) if (e.kind === 'turn.started') { const t = s.turns[e.turnIndex]; if (t) texts.set(e.turnId, { question: t.question, response: t.response }); }\n  const started = events.find((e): e is Extract<CanonicalEvent, { kind: 'session.started' }> => e.kind === 'session.started');\n  const anchor = started?.anchor ? { project: started.anchor.project, node: started.anchor.node, bundle: started.anchor.bundle } : undefined;\n  return { runner, nativeId: s.sessionId, title: s.title, ...(anchor ? { anchor } : {}), ...(cwd ? { cwd } : {}), ...(subagent ? { subagent } : {}), events, texts, manifest: MANIFESTS[runner], turns: s.turns };\n}\n\ntype ParsedSource = { fact: FactSession; cache: Record<string, CacheTurn>; text: Record<string, TextTurn>; names: Record<string, string>; bundles: FactIndex['bundles'] };\n\nasync function parseSession(f: FileStat): Promise<ParsedSource | null> {\n  if (f.memory) return parseMemory(f, f.memory);\n  const memo = new Map<string, string>();\n  const sourceId = await canonicalPath(f.file, memo);\n  const p = await eventsOf(f.file, sourceId);\n  if (!p) return null;\n  const cwd = p.cwd ? await canonicalPath(p.cwd, memo) : '';\n  const workspace = cwd ? await workspaceOf(cwd) : '';\n  // the index is a reduction of the contract: touches per turn, keyed by\n  // canonical artifact id; names kept for artifacts that are not files\n  const names: Record<string, string> = {};\n  const opsByTurn = new Map<string, Record<string, Touch>>();\n  for (const t of deriveTouches(p.events)) {\n    const id = await canonicalArtifact(t.artifact, memo);\n    const ops = opsByTurn.get(t.turnId) ?? opsByTurn.set(t.turnId, {}).get(t.turnId)!;\n    const prev = ops[id];\n    const d = prev?.d ?? t.change;\n    const l = [...(prev?.l ?? []), ...(t.locators ?? [])].filter((x, i, arr) => arr.findIndex((y) => JSON.stringify(y) === JSON.stringify(x)) === i);\n    ops[id] = { op: strongest(prev?.op, t.op as Op), ...(d ? { d } : {}), ...(l.length ? { l } : {}) };\n  }\n  for (const e of p.events) if (e.kind === 'artifact.attached' && e.artifact.observedPath && !e.artifact.id.startsWith('file://')) names[e.artifact.id] = e.artifact.observedPath;\n  const bundles: FactIndex['bundles'] = {};\n  for (const e of p.events) if (e.kind === 'context.committed' && e.hashOf === 'bundle' && e.turnId) bundles[e.requestId] = { canvas: p.nativeId, node: e.turnId.split('#').pop() ?? '' };\n  const questions = new Map<string, string>();\n  for (const e of p.events) if (e.kind === 'message.recorded' && e.role === 'user' && !questions.has(e.turnId)) questions.set(e.turnId, e.excerpt);\n  const turns: FactTurn[] = [];\n  const cache: Record<string, CacheTurn> = {};\n  const text_: Record<string, TextTurn> = {};\n  let lastSubstantive = '';\n  const starts = p.events.filter((e): e is Extract<CanonicalEvent, { kind: 'turn.started' }> => e.kind === 'turn.started').sort((a, b) => a.turnIndex - b.turnIndex);\n  for (const ts of starts) {\n    const text = p.texts.get(ts.turnId);\n    const q = text ? questionExcerpt(text.question) : (questions.get(ts.turnId) ?? (ts.mirrorOf ? '(mirrored turn)' : ''));\n    // the id that makes a replayed turn count once across files: the\n    // runner's own message id, or the mirrored turn's\n    // A replayed record (a continued session carries its parent's turns\n    // under the same message ids) counts once; a runner REUSING an id for a\n    // new segment (~2) is a new turn and keeps its suffix.\n    const item = ts.mirrorOf?.item ?? (p.runner === 'thoughtdag' ? ts.turnId : ts.turnId.split('#').pop());\n    turns.push({ i: ts.turnIndex, t: ts.turnId, ...(item ? { item } : {}), ...(ts.at ? { at: ts.at } : {}), q, ops: opsByTurn.get(ts.turnId) ?? {} });\n    if (!text) continue;\n    // the words a turn can be found by — verbatim, all of them\n    if (text.question.trim() || text.response.trim() || text.material?.trim()) {\n      text_[String(ts.turnIndex)] = { q: text.question, a: text.response, ...(text.material ? { m: text.material } : {}) };\n    }\n    const entry: CacheTurn = {};\n    const con = conclusionOf(text.response, 240);\n    if (con) entry.c = con;\n    if (q.length < 12 && lastSubstantive) entry.p = lastSubstantive;\n    if (q.length >= 12) lastSubstantive = q;\n    for (const id of Object.keys(opsByTurn.get(ts.turnId) ?? {})) {\n      const m = mentionOf(text.response, mentionKey(names[id] ? `file://${names[id]}` : id));\n      if (m) (entry.m ??= {})[id] = m;\n    }\n    if (Object.keys(entry).length) cache[String(ts.turnIndex)] = entry;\n  }\n  return {\n    fact: { id: p.nativeId, runner: p.runner, file: f.file, mtime: f.mtime, size: f.size, cwd, workspace, title: p.title, ...(p.subagent ? { subagent: true } : {}), ...(p.anchor ? { anchor: p.anchor } : {}), turns },\n    cache, text: text_, names, bundles,\n  };\n}\n\n// ─── memories ────────────────────────────────────────────────────────\n//\n// A memory file becomes one session of kind 'memory'; its entries are the\n// turns. What counts as an entry follows each file's own shape, read off\n// its headings — no model, no guessing beyond the markdown.\n\ninterface MemoryUnit { heading: string; body: string; cwd?: string; at?: string }\ninterface MemoryFile { title: string; cwd: string; units: MemoryUnit[] }\n\n/** Frontmatter (--- … ---) as flat key: value pairs, and the text after it. */\nfunction frontmatterOf(text: string): { meta: Record<string, string>; body: string } {\n  const m = /^---\\r?\\n([\\s\\S]*?)\\r?\\n---\\r?\\n?/.exec(text);\n  if (!m) return { meta: {}, body: text };\n  const meta: Record<string, string> = {};\n  for (const line of m[1].split(/\\r?\\n/)) {\n    const kv = /^\\s*([A-Za-z_][\\w-]*):\\s*(.*)$/.exec(line);\n    if (kv && kv[2].trim()) meta[kv[1]] = kv[2].trim();\n  }\n  return { meta, body: text.slice(m[0].length) };\n}\n\n/** The sections of a markdown text at one heading level: heading text and\n *  the body under it (until the next heading of that level or a higher one). */\nfunction sectionsOf(text: string, level: number): { heading: string; body: string }[] {\n  const out: { heading: string; body: string }[] = [];\n  const lines = text.split(/\\r?\\n/);\n  let cur: { heading: string; body: string[] } | null = null;\n  const isBoundary = (line: string): number | null => { const m = /^(#{1,6})\\s+(.*)$/.exec(line); return m && m[1].length <= level ? m[1].length : null; };\n  for (const line of lines) {\n    const lvl = isBoundary(line);\n    if (lvl === level) { if (cur) out.push({ heading: cur.heading, body: cur.body.join('\\n').trim() }); cur = { heading: line.replace(/^#+\\s+/, '').trim(), body: [] }; continue; }\n    if (lvl !== null && lvl < level) { if (cur) out.push({ heading: cur.heading, body: cur.body.join('\\n').trim() }); cur = null; continue; }\n    if (cur) cur.body.push(line);\n  }\n  if (cur) out.push({ heading: cur.heading, body: cur.body.join('\\n').trim() });\n  return out;\n}\n\nconst metaLine = (body: string, key: string): string | undefined => {\n  const m = new RegExp(`^${key}:\\\\s*(.+)$`, 'm').exec(body);\n  return m ? m[1].trim() : undefined;\n};\n\n// the working directory a Claude Code project directory stands for: read off\n// one of its session files (every record carries cwd), remembered per directory\nconst claudeCwdMemo = new Map<string, Promise<string>>();\nfunction claudeProjectCwd(projectDir: string): Promise<string> {\n  let p = claudeCwdMemo.get(projectDir);\n  if (!p) {\n    p = (async () => {\n      let entries: string[] = [];\n      try { entries = (await fsp.readdir(projectDir)).filter((n) => n.endsWith('.jsonl')).sort(); } catch { return ''; }\n      for (const n of entries) {\n        try { const o = JSON.parse(await firstLine(path.join(projectDir, n))) as { cwd?: unknown }; if (typeof o.cwd === 'string' && o.cwd) return o.cwd; } catch { /* not a record */ }\n      }\n      return '';\n    })();\n    claudeCwdMemo.set(projectDir, p);\n  }\n  return p;\n}\n\n/** One memory file, read into its entries. */\nasync function memoryFile(file: string, runner: MemoryRunner): Promise<MemoryFile | null> {\n  let text: string;\n  try { text = await fsp.readFile(file, 'utf8'); } catch { return null; }\n  const base = path.basename(file);\n  if (runner === 'claude-code') {\n    const projectDir = path.dirname(path.dirname(file));\n    const cwd = await claudeProjectCwd(projectDir);\n    const { meta, body } = frontmatterOf(text);\n    const heading = meta.description || meta.name || base.replace(/\\.md$/, '');\n    const project = path.basename(cwd || projectDir);\n    return { title: `memory · ${project} · ${base.replace(/\\.md$/, '')}`, cwd, units: body.trim() ? [{ heading, body: body.trim() }] : [] };\n  }\n  // codex\n  if (base === 'MEMORY.md') {\n    const units: MemoryUnit[] = [];\n    for (const g of sectionsOf(text, 1)) {\n      const cwd = /cwd=([^;\\n]+)/.exec(metaLine(g.body, 'applies_to') ?? '')?.[1]?.trim();\n      const subs = sectionsOf(g.body, 2);\n      if (!subs.length) { units.push({ heading: g.heading, body: g.body, ...(cwd ? { cwd } : {}) }); continue; }\n      for (const u of subs) units.push({ heading: `${g.heading} › ${u.heading}`, body: u.body, ...(cwd ? { cwd } : {}) });\n    }\n    return { title: 'memory · Codex · MEMORY.md', cwd: '', units };\n  }\n  if (base === 'raw_memories.md') {\n    const units: MemoryUnit[] = sectionsOf(text, 2).map((u) => {\n      const cwd = metaLine(u.body, 'cwd'); const at = metaLine(u.body, 'updated_at');\n      const heading = cwd ? `${u.heading} · ${path.basename(cwd)}` : u.heading;\n      return { heading, body: u.body, ...(cwd ? { cwd } : {}), ...(at ? { at: new Date(at).toISOString() } : {}) };\n    });\n    return { title: 'memory · Codex · raw_memories.md', cwd: '', units };\n  }\n  const subs = sectionsOf(text, 2);\n  if (subs.length) return { title: `memory · Codex · ${base}`, cwd: '', units: subs };\n  const h1 = sectionsOf(text, 1)[0];\n  return { title: `memory · Codex · ${base}`, cwd: '', units: text.trim() ? [{ heading: h1?.heading ?? base, body: text.trim() }] : [] };\n}\n\nconst shortHash = (s: string): string => createHash('sha1').update(s).digest('hex').slice(0, 12);\n\nasync function parseMemory(f: FileStat, runner: MemoryRunner): Promise<ParsedSource | null> {\n  const mf = await memoryFile(f.file, runner);\n  if (!mf || !mf.units.length) return null;\n  const memo = new Map<string, string>();\n  const cwd = mf.cwd ? await canonicalPath(mf.cwd, memo) : '';\n  const workspace = cwd ? await workspaceOf(cwd) : '';\n  const at = new Date(f.mtime).toISOString();\n  const turns: FactTurn[] = [];\n  const text: Record<string, TextTurn> = {};\n  for (const [i, u] of mf.units.entries()) {\n    const unitCwd = u.cwd ? await canonicalPath(u.cwd, memo) : '';\n    turns.push({ i, t: `memory#${i}`, at: u.at ?? at, q: questionExcerpt(u.heading), ops: {}, ...(unitCwd && unitCwd !== cwd ? { cwd: unitCwd } : {}) });\n    text[String(i)] = { q: u.heading, a: u.body };\n  }\n  const id = `mem-${runner === 'codex' ? 'cx' : 'cc'}-${shortHash(await canonicalPath(f.file, memo))}`;\n  return {\n    fact: { id, runner, kind: 'memory', file: f.file, mtime: f.mtime, size: f.size, cwd, workspace, title: mf.title, turns },\n    cache: {}, text, names: {}, bundles: {},\n  };\n}\n\n// ─── stores ──────────────────────────────────────────────────────────\n\nconst emptyFacts = (): FactIndex => ({ version: INDEX_VERSION, builtAt: '', sessions: {}, skipped: {}, names: {}, bundles: {} });\nconst emptyCache = (): CacheIndex => ({ version: INDEX_VERSION, sessions: {} });\nconst emptyText = (): TextIndex => ({ version: INDEX_VERSION, sessions: {} });\n\nasync function readJson<T>(file: string, empty: () => T): Promise<T> {\n  try {\n    const v = JSON.parse(await fsp.readFile(file, 'utf8')) as T & { version?: number };\n    return v.version === INDEX_VERSION ? v : empty();\n  } catch { return empty(); }\n}\n\n/** A temp name no other process can be using: pid and a time tag. Two\n *  queries refreshing at once used to share one `.tmp` and one of them\n *  lost the rename race. */\nconst tmpFor = (file: string): string => `${file}.${process.pid}.${Date.now().toString(36)}.tmp`;\n\nconst LOCK_FILE = path.join(HOME, 'index.lock');\nconst LOCK_STALE_MS = 10 * 60_000;\n\n/** One refresher at a time. Returns a release function, or null when\n *  another live process holds the lock. A lock left by a dead process\n *  (or older than ten minutes) is broken. */\nasync function acquireLock(file = LOCK_FILE, staleMs = LOCK_STALE_MS): Promise<(() => Promise<void>) | null> {\n  await fsp.mkdir(HOME, { recursive: true, mode: 0o700 });\n  for (let attempt = 0; attempt < 2; attempt++) {\n    try {\n      const fh = await fsp.open(file, 'wx', 0o600);\n      await fh.writeFile(JSON.stringify({ pid: process.pid, at: Date.now() }));\n      await fh.close();\n      return async () => { await fsp.rm(file, { force: true }).catch(() => undefined); };\n    } catch (err) {\n      if ((err as NodeJS.ErrnoException).code !== 'EEXIST') throw err;\n      let holder: { pid?: number; at?: number } = {};\n      try { holder = JSON.parse(await fsp.readFile(file, 'utf8')) as typeof holder; } catch { /* unreadable: treat as stale */ }\n      const alive = (() => { if (!holder.pid) return false; try { process.kill(holder.pid, 0); return true; } catch { return false; } })();\n      const stale = !alive || !holder.at || Date.now() - holder.at > staleMs;\n      if (!stale) return null;\n      await fsp.rm(file, { force: true }).catch(() => undefined);\n    }\n  }\n  return null;\n}\n\n/** Wait for another process's refresh to finish (the lock to disappear),\n *  bounded; true when it did. */\nasync function waitForLock(maxMs = 20_000): Promise<boolean> {\n  const t0 = Date.now();\n  while (Date.now() - t0 < maxMs) {\n    try { await fsp.access(LOCK_FILE); } catch { return true; }\n    await new Promise((r) => setTimeout(r, 150));\n  }\n  return false;\n}\n\n/** Private by construction: the directory is 0700, every file 0600, and\n *  a write never leaves a half-written index behind. */\nasync function writePrivate(file: string, data: unknown): Promise<void> {\n  await fsp.mkdir(HOME, { recursive: true, mode: 0o700 });\n  await fsp.chmod(HOME, 0o700).catch(() => undefined);\n  const tmp = tmpFor(file);\n  await fsp.writeFile(tmp, JSON.stringify(data), { mode: 0o600 });\n  await fsp.chmod(tmp, 0o600).catch(() => undefined);\n  await fsp.rename(tmp, file);\n}\n\nconst loadFacts = async (): Promise<FactIndex> => {\n  const f = await readJson(FACT_FILE, emptyFacts);\n  f.skipped ??= {}; f.sessions ??= {}; f.names ??= {}; f.bundles ??= {};\n  return f;\n};\nconst loadCache = (): Promise<CacheIndex> => readJson(CACHE_FILE, emptyCache);\nconst loadText = (): Promise<TextIndex> => readJson(TEXT_FILE, emptyText);\n\n// ─── index ───────────────────────────────────────────────────────────\n\ninterface BuildReport { parsed: number; kept: number; skipped: number; removed: number; seconds: number; waited?: boolean }\n\n/** The text lines file is rewritten by streaming: lines of unchanged\n *  sources pass through, lines of re-read or vanished sources are dropped,\n *  new lines are appended. Never held in memory whole. */\nasync function rewriteTextLines(replaced: Map<string, Record<string, TextTurn>>, removed: Set<string>, full: boolean): Promise<void> {\n  await fsp.mkdir(HOME, { recursive: true, mode: 0o700 });\n  const tmp = tmpFor(TEXT_LINES);\n  const out = createWriteStream(tmp, { mode: 0o600 });\n  const write = (line: string): Promise<void> => new Promise((res, rej) => { out.write(line + '\\n', (e) => (e ? rej(e) : res())); });\n  if (!full) {\n    let old: ReturnType<typeof createInterface> | null = null;\n    try { await fsp.access(TEXT_LINES); old = createInterface({ input: createReadStream(TEXT_LINES, { encoding: 'utf8', highWaterMark: 1 << 20 }) }); } catch { /* first build */ }\n    if (old) {\n      for await (const line of old) {\n        const at = line.indexOf('\"k\":\"'); if (at < 0) continue;\n        const k = JSON.parse(line.slice(at + 4, line.indexOf('\"', at + 5) + 1)) as string;\n        if (replaced.has(k) || removed.has(k)) continue;\n        await write(line);\n      }\n    }\n  }\n  for (const [k, turns] of replaced) {\n    for (const [i, t] of Object.entries(turns)) await write(JSON.stringify({ k, i: Number(i), ...t } satisfies TextLine));\n  }\n  await new Promise<void>((res, rej) => out.end((e?: Error | null) => (e ? rej(e) : res())));\n  await fsp.chmod(tmp, 0o600).catch(() => undefined);\n  await fsp.rename(tmp, TEXT_LINES);\n}\n\nasync function buildIndex(full: boolean, canvasDir?: string): Promise<BuildReport> {\n  const t0 = Date.now();\n  if (canvasDir) await rememberCanvasRoot(canvasDir);\n  // one refresher at a time; a second caller waits for the first and\n  // then simply reads what it wrote\n  const release = await acquireLock();\n  if (!release) {\n    const done = await waitForLock();\n    return { parsed: 0, kept: 0, skipped: 0, removed: 0, seconds: (Date.now() - t0) / 1000, waited: done };\n  }\n  try {\n    return await buildIndexLocked(full, t0);\n  } finally {\n    await release();\n  }\n}\n\nasync function buildIndexLocked(full: boolean, t0: number): Promise<BuildReport> {\n  await fsp.rm(LEGACY_FILE, { force: true }).catch(() => undefined);\n  const facts = full ? emptyFacts() : await loadFacts();\n  const cache = full ? emptyCache() : await loadCache();\n  const text = full ? emptyText() : await loadText();\n  const files = await listSources();\n  let parsed = 0, kept = 0, skipped = 0, removed = 0;\n  const seen = new Set<string>();\n  const replacedText = new Map<string, Record<string, TextTurn>>();\n  const removedKeys = new Set<string>();\n  for (const f of files) {\n    const key = await canonicalPath(f.file);\n    seen.add(key);\n    const prev = facts.sessions[key];\n    const sk = facts.skipped[key];\n    if (sk && sk.mtime === f.mtime && sk.size === f.size) { skipped++; continue; }\n    // unchanged AND its interpretation is still there: a deleted cache\n    // must come back on the next index, or \"deletable\" was a lie\n    // presence, not truthiness: a session with no text at all (an empty rollout) is still indexed\n    if (prev && prev.mtime === f.mtime && prev.size === f.size && key in cache.sessions && key in text.sessions) { kept++; continue; }\n    const r = await parseSession(f).catch(() => null);\n    if (!r) { facts.skipped[key] = { mtime: f.mtime, size: f.size }; skipped++; continue; }\n    delete facts.skipped[key];\n    facts.sessions[key] = r.fact;\n    cache.sessions[key] = r.cache;\n    replacedText.set(key, r.text);\n    text.sessions[key] = Object.keys(r.text).length;\n    Object.assign(facts.names, r.names);\n    Object.assign(facts.bundles, r.bundles);\n    parsed++;\n  }\n  for (const key of Object.keys(facts.sessions)) {\n    if (!seen.has(key)) { delete facts.sessions[key]; delete cache.sessions[key]; delete text.sessions[key]; removedKeys.add(key); removed++; }\n  }\n  for (const key of Object.keys(facts.skipped)) if (!seen.has(key)) delete facts.skipped[key];\n  facts.builtAt = new Date().toISOString();\n  await writePrivate(FACT_FILE, facts);\n  await writePrivate(CACHE_FILE, cache);\n  if (full || replacedText.size || removedKeys.size) await rewriteTextLines(replacedText, removedKeys, full);\n  await writePrivate(TEXT_FILE, text);\n  return { parsed, kept, skipped, removed, seconds: (Date.now() - t0) / 1000 };\n}\n\n/** A query answers from the present: when any source changed since the\n *  index was built, refresh incrementally first (usually well under a\n *  second thanks to the per-file watermark). */\n// A host that embeds this library (the DeepSeek Harness plugin) speaks to no\n// terminal: it silences the refresh notices the command line prints.\nlet quiet = false;\nexport function setQuiet(v: boolean): void { quiet = v; }\n\nasync function ensureFresh(): Promise<FactIndex> {\n  const facts = await loadFacts();\n  const cache = await loadCache();\n  const text = await loadText();\n  const files = await listSources();\n  const keyed = await Promise.all(files.map(async (f) => ({ ...f, key: await canonicalPath(f.file) })));\n  const known = (f: FileStat & { key: string }): boolean => {\n    const p = facts.sessions[f.key];\n    if (p) return p.mtime === f.mtime && p.size === f.size && f.key in cache.sessions && f.key in text.sessions;\n    const sk = facts.skipped[f.key];\n    return !!sk && sk.mtime === f.mtime && sk.size === f.size;\n  };\n  const stale = !facts.builtAt\n    || keyed.some((f) => !known(f))\n    || Object.keys(facts.sessions).length + Object.keys(facts.skipped).length !== keyed.length;\n  if (!stale) return facts;\n  const r = await buildIndex(false);\n  if (!quiet) {\n    if (r.waited !== undefined) console.error(r.waited ? '(index refreshed by another process)' : '(index refresh in progress elsewhere; answering from the current index)');\n    else console.error(`(index refreshed: ${r.parsed} session${r.parsed === 1 ? '' : 's'} re-read, ${r.removed} gone, ${r.seconds.toFixed(1)}s)`);\n  }\n  return loadFacts();\n}\n\ninterface Stats { sessions: number; sources: number; turns: number; artifacts: { file: number; url: number; arxiv: number; other: number }; touches: number; changes: number; withChangeHead: number; withMention: number; memoryFiles: number; memoryEntries: number }\nconst schemeOf = (id: string): keyof Stats['artifacts'] => id.startsWith('file://') ? 'file' : id.startsWith('arxiv:') ? 'arxiv' : /^https?:\\/\\//.test(id) ? 'url' : 'other';\nconst artifactsLine = (a: Stats['artifacts']): string => [`${a.file} files`, a.url ? `${a.url} urls` : '', a.arxiv ? `${a.arxiv} papers` : '', a.other ? `${a.other} other` : ''].filter(Boolean).join(' · ');\n\nfunction summarize(facts: FactIndex, cache: CacheIndex): Stats {\n  const seen = new Set<string>();\n  const artifacts = { file: 0, url: 0, arxiv: 0, other: 0 };\n  let turns = 0, touches = 0, changes = 0, withChangeHead = 0, withMention = 0;\n  for (const [key, s] of Object.entries(facts.sessions)) {\n    turns += s.turns.length;\n    for (const t of s.turns) {\n      const ct = cache.sessions[key]?.[String(t.i)];\n      for (const [p, x] of Object.entries(t.ops)) {\n        if (!seen.has(p)) { seen.add(p); artifacts[schemeOf(p)]++; }\n        touches++;\n        if (!readLike(x.op)) { changes++; if (x.d) withChangeHead++; }\n        if (ct?.m?.[p]) withMention++;\n      }\n    }\n  }\n  const sessions = new Set(Object.values(facts.sessions).map((s) => s.id)).size;\n  const mem = Object.values(facts.sessions).filter((s) => s.kind === 'memory');\n  return { sessions, sources: Object.keys(facts.sessions).length, turns, artifacts, touches, changes, withChangeHead, withMention, memoryFiles: mem.length, memoryEntries: mem.reduce((n, s) => n + s.turns.length, 0) };\n}\n\n// ─── why ─────────────────────────────────────────────────────────────\n\ninterface Hit { session: FactSession; sourceKey: string; turn: FactTurn; touch: Touch }\n\nconst allPaths = (facts: FactIndex): Set<string> => {\n  const all = new Set<string>();\n  for (const s of Object.values(facts.sessions)) for (const t of s.turns) for (const p of Object.keys(t.ops)) all.add(p);\n  return all;\n};\n\n/** Exact path first (as typed, then canonical). A bare name matches by\n *  suffix — inside this workspace unless --all: the same file name lives\n *  in many projects, and the question is about this one. */\nasync function resolveQuery(facts: FactIndex, rawArg: string, all: boolean): Promise<{ path: string | null; candidates: string[]; elsewhere: number }> {\n  // agents hand us paths as their host writes them: `@file` (a Claude Code\n  // reference), quoted, or with a trailing colon — the target is the path\n  const arg = rawArg.trim().replace(/^@/, '').replace(/^[\"'`]|[\"'`:]+$/g, '');\n  const ids = allPaths(facts);\n  // a web resource or a paper has one exact identity — no suffix games\n  const web = urlArtifact(arg) ?? arxivArtifact(arg);\n  if (web) return ids.has(web.id) ? { path: web.id, candidates: [web.id], elsewhere: 0 } : { path: null, candidates: [], elsewhere: 0 };\n  if (arg.startsWith('thoughtdag:')) return ids.has(arg) ? { path: arg, candidates: [arg], elsewhere: 0 } : { path: null, candidates: [], elsewhere: 0 };\n  // a canvas attachment answers to its file name\n  const named = Object.entries(facts.names).filter(([, name]) => name === arg || name.endsWith(`/${arg}`)).map(([id]) => id);\n  if (named.length === 1) return { path: named[0], candidates: named, elsewhere: 0 };\n  const abs = absolutePath(arg, process.cwd());\n  if (abs) {\n    const typed = fileUri(abs);\n    if (ids.has(typed)) return { path: typed, candidates: [typed], elsewhere: 0 };\n    const real = fileUri(await canonicalPath(abs));\n    if (ids.has(real)) return { path: real, candidates: [real], elsewhere: 0 };\n  }\n  const needle = arg.replace(/\\\\/g, '/').replace(/^\\.\\//, '').replace(/\\/+$/, '');\n  const files = [...ids].flatMap((id) => { const p = filePathOf(id); return p ? [{ id, p }] : []; });\n  const bySuffix = files.filter(({ p }) => p === needle || p.endsWith(`/${needle}`));\n  const ws = (await workspaceOf(process.cwd())).replace(/\\\\/g, '/');\n  const inside = all ? bySuffix : bySuffix.filter(({ p }) => p.startsWith(`${ws}/`));\n  if (inside.length === 1) return { path: inside[0].id, candidates: [inside[0].p], elsewhere: bySuffix.length - inside.length };\n  return { path: null, candidates: inside.map((x) => x.p).sort(), elsewhere: bySuffix.length - inside.length };\n}\n\n/** Every turn that touched the file, once each: a continued session\n *  replays the turns it continued from under the same message ids, and\n *  those belong to the session that first recorded them. */\nfunction hitsFor(facts: FactIndex, artifact: string, includeRead: boolean): { hits: Hit[]; readsHidden: number } {\n  const all: Hit[] = [];\n  const seen = new Set<string>();\n  const sources = Object.entries(facts.sessions).sort((a, b) => a[1].mtime - b[1].mtime);\n  for (const [sourceKey, session] of sources) {\n    for (const turn of session.turns) {\n      const touch = turn.ops[artifact];\n      if (!touch) continue;\n      if (turn.item) { if (seen.has(turn.item)) continue; seen.add(turn.item); }\n      all.push({ session, sourceKey, turn, touch });\n    }\n  }\n  // reads hide behind changes; an artifact that was only ever read (or\n  // fetched — a paper, a page) shows its reads, or there is nothing to say\n  const hasChanges = all.some((h) => !readLike(h.touch.op));\n  if (includeRead || !hasChanges) return { hits: all, readsHidden: 0 };\n  const hits = all.filter((h) => !readLike(h.touch.op));\n  return { hits, readsHidden: all.length - hits.length };\n}\n\n/** An anchor is a CLAIM in a session's first message. It is matched when\n *  an indexed canvas logged that bundle's hand-off from that node,\n *  mismatched when the bundle exists but names another node, unverified\n *  when no indexed canvas knows the bundle (older hand-offs, or a canvas\n *  folder not yet indexed). */\ntype AnchorStatus = 'matched' | 'mismatch' | 'unverified';\nfunction anchorStatus(facts: FactIndex, a: NonNullable<FactSession['anchor']>): AnchorStatus {\n  const b = facts.bundles[a.bundle];\n  if (!b) return 'unverified';\n  return b.node === a.node ? 'matched' : 'mismatch';\n}\n\n/** Where a hit opens: the mirrored session at that very turn, or the\n *  canvas project at that node. */\nfunction openLink(h: { session: FactSession; turn: FactTurn }): string {\n  // a memory entry: the file and the entry's number\n  if (h.session.kind === 'memory') return `thoughtdag://open?memory=${encodeURIComponent(h.session.file)}&entry=${h.turn.i}`;\n  // canvas: the project's own id when the backup carried one, its name otherwise\n  if (h.session.runner === 'thoughtdag') return `thoughtdag://open?canvas=${encodeURIComponent(h.session.id)}&node=${encodeURIComponent(h.turn.t.split('#').pop() ?? '')}`;\n  return `thoughtdag://open?session=${h.session.id}${h.turn.item ? `&turn=${encodeURIComponent(h.turn.item)}` : ''}`;\n}\n\nconst OP_MARK: Record<Op, string> = { edit: '✏️ edit ', write: '✏️ write', read: '📖 read ', fetch: '🌐 fetch', attach: '📎 attach' };\nfunction when(t: FactTurn, s: FactSession): string {\n  const d = new Date(t.at ?? s.mtime);\n  const p = (n: number) => String(n).padStart(2, '0');\n  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;\n}\n\nconst EVIDENCE = {\n  footprint: 'observed',\n  change: 'observed, partial (first differing line)',\n  askedBefore: 'inferred (the earlier question a bare reply answers)',\n  about: 'inferred (a paragraph of the answer naming the file)',\n  conclusion: 'inferred (the answer\\'s closing paragraph)',\n} as const;\n\n/** Turn numbers count through a logical session's fragments in time\n *  order, so `#n` in why and `recall <session> n` agree even when the\n *  runner split the session across files. */\nfunction fragmentsOf(facts: FactIndex, sessionId: string): { key: string; s: FactSession; offset: number }[] {\n  const frags = Object.entries(facts.sessions).filter(([, s]) => s.id === sessionId).sort((a, b) => a[1].mtime - b[1].mtime);\n  let offset = 0;\n  return frags.map(([key, s]) => { const f = { key, s, offset }; offset += s.turns.length; return f; });\n}\nfunction turnNumber(facts: FactIndex, h: { session: FactSession; sourceKey: string; turn: FactTurn }): number {\n  return (fragmentsOf(facts, h.session.id).find((f) => f.key === h.sourceKey)?.offset ?? 0) + h.turn.i;\n}\n\nasync function renderWhy(facts: FactIndex, file: string, hits: Hit[], readsHidden: number, cache: CacheIndex, limit: number, json: boolean): Promise<string> {\n  const out: string[] = [];\n  const bySession = new Map<string, Hit[]>();\n  for (const h of hits) (bySession.get(h.session.id) ?? bySession.set(h.session.id, []).get(h.session.id)!).push(h);\n  const groups = [...bySession.values()]\n    .map((hs) => hs.sort((a, b) => a.turn.i - b.turn.i))\n    .sort((a, b) => (b[b.length - 1].turn.at ?? '').localeCompare(a[a.length - 1].turn.at ?? ''));\n  const shown = new Set<Hit>();\n  for (const g of groups) for (const h of g) if (shown.size < limit) shown.add(h);\n  const interp = (h: Hit): CacheTurn => cache.sessions[h.sourceKey]?.[String(h.turn.i)] ?? {};\n\n  if (json) {\n    out.push(JSON.stringify({\n      artifact: file, file: filePathOf(file), turns: hits.length, sessions: bySession.size, readsHidden, evidence: EVIDENCE,\n      hits: [...shown].map((h) => {\n        const c = interp(h);\n        return {\n          session: h.session.id, runner: h.session.runner, title: h.session.title, subagent: !!h.session.subagent,\n          anchor: h.session.anchor ? { ...h.session.anchor, status: anchorStatus(facts, h.session.anchor) } : null,\n          turn: turnNumber(facts, h), at: h.turn.at ?? null, op: h.touch.op, locators: h.touch.l ?? null, question: h.turn.q,\n          askedBefore: c.p ?? null, change: h.touch.d ?? null, about: c.m?.[file] ?? null, conclusion: c.c ?? null,\n          open: openLink(h),\n        };\n      }),\n    }, null, 1));\n    return out.join('\\n');\n  }\n\n  const label = await displayOf(file, facts.names);\n  const n = hits.length;\n  const head = `why ${label}  ·  ${n} turn${n === 1 ? '' : 's'} in ${bySession.size} session${bySession.size === 1 ? '' : 's'}`;\n  const notes = [\n    readsHidden ? `${readsHidden} read${readsHidden === 1 ? '' : 's'} hidden, --include-read` : '',\n    n > limit ? `showing ${limit}, --limit for more` : '',\n  ].filter(Boolean);\n  out.push(`${head}${notes.length ? `  (${notes.join('; ')})` : ''}\\n`);\n  let printed = 0;\n  for (const g of groups) {\n    const mine = g.filter((h) => shown.has(h));\n    if (!mine.length) continue;\n    const s = g[0].session;\n    out.push(`${s.runner}  「${s.title.slice(0, 70)}」${s.subagent ? '  (subagent)' : ''}${s.anchor ? `  ↩ from canvas node ${s.anchor.node} (${s.anchor.bundle}, ${anchorStatus(facts, s.anchor)})` : ''}`);\n    for (const h of mine) {\n      const c = interp(h);\n      const where = h.touch.l?.map((l) => l.pages ? `p.${l.pages}` : l.lines ? `L${l.lines[0]}-${l.lines[1]}` : '').filter(Boolean).join(' ');\n      out.push(`  ${when(h.turn, s)}  ${OP_MARK[h.touch.op]}  #${turnNumber(facts, h)}${where ? `  ${where}` : ''}  ${openLink(h)}`);\n      out.push(`    Q: ${h.turn.q}${c.p ? `   ⤴ ${c.p}` : ''}`);\n      if (h.touch.d) out.push(`    Δ ${h.touch.d}`);\n      const about = c.m?.[file];\n      if (about) out.push(`    ≈ ${about}`);\n      else if (c.c) out.push(`    ≈ ${c.c}   (closing line)`);\n      printed++;\n    }\n    out.push('');\n  }\n  if (!printed) out.push('(no turns)\\n');\n  out.push('Δ observed change · ≈ read from the answer, a candidate explanation, not a verified reason · ⤴ the earlier question this reply answers');\n  return out.join('\\n');\n}\n\n// ─── find ────────────────────────────────────────────────────────────\n\n/** Exact phrase, case-insensitive, over everything that was said: the\n *  questions (Q), the answers (A) and the text of attached materials (M),\n *  all verbatim. Recall is bounded by wording — a synonym is not a hit —\n *  and every hit is a quote with a pointer, never a guess. */\ninterface FindHit { session: FactSession; sourceKey: string; turn: FactTurn; where: 'Q' | 'A' | 'M'; snippet: string; kind: 'turn' | 'memory' }\n\nfunction snippetAround(text: string, needle: string, width = 70): string {\n  const at = text.toLowerCase().indexOf(needle);\n  if (at < 0) return '';\n  const start = Math.max(0, at - width); const end = Math.min(text.length, at + needle.length + width);\n  return `${start > 0 ? '…' : ''}${text.slice(start, end).replace(/\\s+/g, ' ').trim()}${end < text.length ? '…' : ''}`;\n}\n\nasync function findHits(facts: FactIndex, phrase: string, scope: 'q' | 'a' | 'm' | 'all'): Promise<FindHit[]> {\n  const needle = phrase.toLowerCase();\n  const turnsOf = new Map<string, Map<number, FactTurn>>();\n  const lookup = (k: string, i: number): FactTurn | undefined => {\n    let m = turnsOf.get(k);\n    if (!m) { m = new Map(facts.sessions[k]?.turns.map((t) => [t.i, t]) ?? []); turnsOf.set(k, m); }\n    return m.get(i);\n  };\n  const raw: FindHit[] = [];\n  let lines: ReturnType<typeof createInterface> | null = null;\n  try { await fsp.access(TEXT_LINES); lines = createInterface({ input: createReadStream(TEXT_LINES, { encoding: 'utf8', highWaterMark: 1 << 20 }) }); } catch { return []; }\n  for await (const line of lines) {\n    // cheap gate before any parsing: the phrase must be somewhere in the line\n    if (!line.toLowerCase().includes(needle)) continue;\n    let t: TextLine;\n    try { t = JSON.parse(line) as TextLine; } catch { continue; }\n    const session = facts.sessions[t.k]; const turn = lookup(t.k, t.i);\n    if (!session || !turn) continue;\n    const fields: ['Q' | 'A' | 'M', string | undefined][] = [['Q', t.q], ['A', t.a], ['M', t.m]];\n    for (const [where, body] of fields) {\n      if (!body) continue;\n      if (scope !== 'all' && where.toLowerCase() !== scope) continue;\n      if (!body.toLowerCase().includes(needle)) continue;\n      raw.push({ session, sourceKey: t.k, turn, where, snippet: snippetAround(body, needle), kind: session.kind === 'memory' ? 'memory' : 'turn' });\n      break; // one hit per turn, the strongest field first\n    }\n  }\n  // a replayed turn counts once, credited to the session that first recorded it\n  const seen = new Set<string>();\n  const hits: FindHit[] = [];\n  for (const h of raw.sort((a, b) => a.session.mtime - b.session.mtime)) {\n    if (h.turn.item) { if (seen.has(h.turn.item)) continue; seen.add(h.turn.item); }\n    hits.push(h);\n  }\n  return hits.sort((a, b) => (b.turn.at ?? '').localeCompare(a.turn.at ?? ''));\n}\n\nfunction renderFind(facts: FactIndex, phrase: string, hits: FindHit[], limit: number, json: boolean): string {\n  const out: string[] = [];\n  const shown = hits.slice(0, limit);\n  const sessions = new Set(hits.map((h) => h.session.id)).size;\n  if (json) {\n    out.push(JSON.stringify({ phrase, turns: hits.length, sessions, evidence: { Q: 'observed (a question, verbatim)', A: 'observed (an answer, verbatim)', M: \"observed (an attached material's text, verbatim)\" },\n      hits: shown.map((h) => ({ kind: h.kind, session: h.session.id, runner: h.session.runner, title: h.session.title, cwd: h.turn.cwd ?? h.session.cwd, file: h.session.file, turn: turnNumber(facts, h), at: h.turn.at ?? null, where: h.where, snippet: h.snippet, open: openLink(h) })) }, null, 1));\n    return out.join('\\n');\n  }\n  out.push(`find \"${phrase}\"  ·  ${hits.length} turn${hits.length === 1 ? '' : 's'} in ${sessions} session${sessions === 1 ? '' : 's'}${hits.length > limit ? `  (showing ${limit}, --limit for more)` : ''}\\n`);\n  for (const h of shown) {\n    const s = h.session;\n    out.push(`${when(h.turn, s)}  ${s.runner}${h.kind === 'memory' ? ' memory' : ''}  「${s.title.slice(0, 60)}」  #${turnNumber(facts, h)}  ${openLink(h)}`);\n    out.push(`    ${h.where}: ${h.snippet}`);\n  }\n  if (!shown.length) out.push('(nothing asked, answered or attached in those words — try another wording; matching is exact)');\n  else out.push('\\nQ: asked · A: answered · M: in an attached material — all verbatim; the phrase must appear in those words');\n  return out.join('\\n');\n}\n\n// ─── check ───────────────────────────────────────────────────────────\n\n/** The cheap question an agent asks before touching a file: is there any\n *  history here at all? Facts only, one line, exit code 0 when there is.\n *  Reads a recent index as-is (the last ten minutes), refreshes only when\n *  it is older — a rule that fires before every edit must cost almost\n *  nothing. */\nconst CHECK_FRESH_MS = 10 * 60_000;\n\nasync function factsForCheck(force: boolean): Promise<FactIndex> {\n  const facts = await loadFacts();\n  const age = facts.builtAt ? Date.now() - new Date(facts.builtAt).getTime() : Infinity;\n  return force || age > CHECK_FRESH_MS ? ensureFresh() : facts;\n}\n\nfunction renderCheck(facts: FactIndex, arg: string, file: string | null, hits: Hit[], json: boolean): { text: string; has: boolean } {\n  const changes = hits.filter((h) => !readLike(h.touch.op)).length;\n  const reads = hits.length - changes;\n  const sessions = new Set(hits.map((h) => h.session.id)).size;\n  const latest = hits.map((h) => h.turn.at ?? '').filter(Boolean).sort().pop();\n  const has = hits.length > 0;\n  if (json) return { text: JSON.stringify({ query: arg, artifact: file, history: has, turns: hits.length, sessions, changes, reads, latest: latest ?? null }), has };\n  if (!has) return { text: `${arg}: no history`, has };\n  const parts = [`${hits.length} turn${hits.length === 1 ? '' : 's'} in ${sessions} session${sessions === 1 ? '' : 's'}`, changes ? `${changes} edit${changes === 1 ? '' : 's'}/write${changes === 1 ? '' : 's'}` : '', reads ? `${reads} read${reads === 1 ? '' : 's'}` : '', latest ? `latest ${latest.slice(0, 10)}` : ''].filter(Boolean);\n  return { text: `${arg}: ${parts.join(' · ')}  →  thoughtdag why ${arg}`, has };\n}\n\n// ─── recall ──────────────────────────────────────────────────────────\n\ninterface RecalledTurn {\n  kind: 'turn' | 'memory'; runner: FactSession['runner']; session: string; title: string; turn: number; at?: string; file: string;\n  cwd: string; question: string; response: string; tools: RunnerTurn['tools'];\n}\n\n/** One turn (or one memory entry) in full, by session id prefix and number. */\nasync function recallTurn(facts: FactIndex, sidPrefix: string, n: number): Promise<RecalledTurn> {\n  const any = Object.values(facts.sessions).find((x) => x.id.startsWith(sidPrefix));\n  if (!any) throw new Error(`no session starts with ${sidPrefix}`);\n  // the fragment that holds turn n of the logical session\n  const frag = fragmentsOf(facts, any.id).find((f) => n >= f.offset && n < f.offset + f.s.turns.length);\n  const s = frag?.s ?? any;\n  const local = frag ? n - frag.offset : n;\n  const base = { runner: s.runner, session: s.id, title: s.title, turn: n, file: s.file };\n  if (s.kind === 'memory') {\n    const mf = await memoryFile(s.file, s.runner as MemoryRunner);\n    const u = mf?.units[local];\n    if (!u) throw new Error(`memory ${s.id.slice(0, 8)} has no entry #${n}`);\n    return { ...base, kind: 'memory', at: s.turns[local]?.at, cwd: s.turns[local]?.cwd ?? s.cwd, question: u.heading, response: u.body, tools: [] };\n  }\n  const p = await eventsOf(s.file);\n  const turn = p?.turns?.[local] ?? (() => {\n    // a canvas turn: the node's own text\n    const tid = s.turns[local]?.t;\n    const text = tid ? p?.texts.get(tid) : undefined;\n    return text ? { question: text.question, response: text.response, tools: [] as RunnerTurn['tools'], at: s.turns[local]?.at } : undefined;\n  })();\n  if (!turn) throw new Error(`session ${s.id.slice(0, 8)} has no turn #${n}`);\n  return { ...base, kind: 'turn', at: turn.at, cwd: s.cwd, question: turn.question, response: turn.response, tools: turn.tools };\n}\n\nasync function renderRecall(facts: FactIndex, sidPrefix: string, n: number): Promise<string> {\n  const r = await recallTurn(facts, sidPrefix, n);\n  const out: string[] = [];\n  out.push(`${r.runner}${r.kind === 'memory' ? ' memory' : ''}  「${r.title}」  ${r.kind === 'memory' ? 'entry' : 'turn'} #${n}${r.at ? `  ${r.at.slice(0, 16).replace('T', ' ')}` : ''}\\n`);\n  if (r.kind === 'memory') {\n    out.push(`## ${r.question.trim()}\\n\\n${r.response.trim() || '(empty)'}\\n`);\n    return out.join('\\n');\n  }\n  out.push(`## Question\\n\\n${r.question.trim()}\\n`);\n  out.push(`## Answer\\n\\n${r.response.trim() || '(none)'}\\n`);\n  if (r.tools.length) {\n    out.push(`## Tools (${r.tools.length})\\n`);\n    for (const t of r.tools) {\n      out.push(`- ${t.name}${t.paths?.length ? `  ${t.paths.join(', ')}` : ''}`);\n      if (t.op === 'edit' || t.op === 'write') out.push(t.call.slice(0, 1200).split('\\n').map((l) => `    ${l}`).join('\\n'));\n      // a call the runner answered with an error names no file (#50); the error itself is what the model saw\n      else if (t.op === 'other' && /^error\\b/i.test(t.result.trimStart())) out.push(`    ✗ ${t.result.trim().split('\\n')[0].slice(0, 200)}`);\n    }\n  }\n  return out.join('\\n');\n}\n\n// ─── for a host that shows the answers (the canvas): structured, not rendered ─\n\ninterface FindHitJson { kind: 'turn' | 'memory'; session: string; runner: FactSession['runner']; title: string; cwd: string; file: string; turn: number; at: string | null; where: 'Q' | 'A' | 'M'; snippet: string; open: string }\n\n/** find, as data. `cwd` keeps only hits about that project (a session's\n *  cwd, or a memory entry's own); `limit` defaults to 20. */\nasync function findJson(phrase: string, opts: { scope?: 'q' | 'a' | 'm' | 'all'; limit?: number; cwd?: string } = {}): Promise<{ phrase: string; turns: number; sessions: number; hits: FindHitJson[] }> {\n  const facts = await ensureFresh();\n  let hits = await findHits(facts, phrase, opts.scope ?? 'all');\n  if (opts.cwd) {\n    const want = opts.cwd.replace(/[\\\\/]+$/, '');\n    hits = hits.filter((h) => { const c = h.turn.cwd ?? h.session.cwd; return c === want || c.startsWith(want + path.sep); });\n  }\n  // the limit applies per kind: memory entries carry their file's mtime as\n  // their time and would otherwise crowd every recent turn out of the list\n  const limit = opts.limit ?? 20;\n  const shown = [...hits.filter((h) => h.kind === 'memory').slice(0, limit), ...hits.filter((h) => h.kind === 'turn').slice(0, limit)];\n  return {\n    phrase, turns: hits.length, sessions: new Set(hits.map((h) => h.session.id)).size,\n    hits: shown.map((h) => ({ kind: h.kind, session: h.session.id, runner: h.session.runner, title: h.session.title, cwd: h.turn.cwd ?? h.session.cwd, file: h.session.file, turn: turnNumber(facts, h), at: h.turn.at ?? null, where: h.where, snippet: h.snippet, open: openLink(h) })),\n  };\n}\n\n/** Every turn (and memory entry) the index knows, newest first, with the head of its question and\n *  answer: what a full-reach recall hands the judge, since find's snippets exist only around a phrase.\n *  `total` counts them all; `offset`/`limit` page; `head` is the characters kept of each field. */\ninterface TurnHeadJson { kind: 'turn' | 'memory'; session: string; runner: FactSession['runner']; title: string; cwd: string; file: string; turn: number; at: string | null; q: string; a: string; open: string }\n/** the one background rebuild a stale count may start; null when none is running */\nlet refreshInBackground: Promise<void> | null = null;\nasync function turnsJson(opts: { offset?: number; limit?: number; head?: number } = {}): Promise<{ total: number; turns: TurnHeadJson[]; /** the manifest was stale: a rebuild is running, ask again for the count */ refreshing?: boolean }> {\n  // the count alone comes from the text manifest, at once (the line file is a hundred megabytes on a big\n  // index). A manifest from an earlier index version reads as empty; then the rebuild starts in the\n  // background and the answer says so, instead of holding the caller (and, on the desktop, every other\n  // bridge call on the main process) for the tens of seconds a big index takes (#57). The count is right\n  // once the rebuild has written the manifest; a caller that sees `refreshing` asks again later.\n  if (opts.limit === 0) {\n    // what decides is the manifest's VERSION, not whether it lists sessions: a manifest from an earlier index\n    // version (or none) means a rebuild is due; a current one with no sessions is a genuinely empty index (a\n    // fresh machine), which no rebuild changes, so it counts as 0 rather than refreshing forever (#57)\n    const current = await fsp.readFile(TEXT_FILE, 'utf8').then((raw) => (JSON.parse(raw) as { version?: number }).version === INDEX_VERSION).catch(() => false);\n    if (!current) {\n      refreshInBackground ??= ensureFresh().then(() => undefined, () => undefined).finally(() => { refreshInBackground = null; });\n      return { total: 0, turns: [], refreshing: true };\n    }\n    const text = await loadText();\n    return { total: Object.values(text.sessions).reduce((a, b) => a + b, 0), turns: [] };\n  }\n  const facts = await ensureFresh();\n  const head = Math.max(40, Math.min(1000, opts.head ?? 300));\n  const turnsOf = new Map<string, Map<number, FactTurn>>();\n  const lookup = (k: string, i: number): FactTurn | undefined => {\n    let m = turnsOf.get(k);\n    if (!m) { m = new Map(facts.sessions[k]?.turns.map((t) => [t.i, t]) ?? []); turnsOf.set(k, m); }\n    return m.get(i);\n  };\n  const clipHead = (text: string | undefined): string => (text ?? '').replace(/\\s+/g, ' ').trim().slice(0, head);\n  const raw: { session: FactSession; sourceKey: string; turn: FactTurn; q: string; a: string; kind: 'turn' | 'memory' }[] = [];\n  let lines: ReturnType<typeof createInterface> | null = null;\n  try { await fsp.access(TEXT_LINES); lines = createInterface({ input: createReadStream(TEXT_LINES, { encoding: 'utf8', highWaterMark: 1 << 20 }) }); } catch { return { total: 0, turns: [] }; }\n  for await (const line of lines) {\n    let t: TextLine;\n    try { t = JSON.parse(line) as TextLine; } catch { continue; }\n    const session = facts.sessions[t.k]; const turn = lookup(t.k, t.i);\n    if (!session || !turn) continue;\n    const memory = session.kind === 'memory';\n    raw.push({ session, sourceKey: t.k, turn, q: memory ? '' : clipHead(t.q), a: clipHead(memory ? t.m : t.a), kind: memory ? 'memory' : 'turn' });\n  }\n  // a replayed turn counts once, credited to the session that first recorded it\n  const seen = new Set<string>(); const all: typeof raw = [];\n  for (const h of raw.sort((a, b) => a.session.mtime - b.session.mtime)) {\n    if (h.turn.item) { if (seen.has(h.turn.item)) continue; seen.add(h.turn.item); }\n    all.push(h);\n  }\n  all.sort((a, b) => (b.turn.at ?? '').localeCompare(a.turn.at ?? ''));\n  const offset = Math.max(0, opts.offset ?? 0); const limit = Math.max(0, opts.limit ?? all.length);\n  return {\n    total: all.length,\n    turns: all.slice(offset, offset + limit).map((h) => ({ kind: h.kind, session: h.session.id, runner: h.session.runner, title: h.session.title, cwd: h.turn.cwd ?? h.session.cwd, file: h.session.file, turn: turnNumber(facts, h), at: h.turn.at ?? null, q: h.q, a: h.a, open: openLink(h) })),\n  };\n}\n\n/** recall, as data. */\nasync function recallJson(session: string, n: number): Promise<RecalledTurn> {\n  return recallTurn(await ensureFresh(), session, n);\n}\n\ninterface MemoryFileJson { id: string; runner: FactSession['runner']; file: string; title: string; cwd: string; entries: number; mtime: number; headings: string[] }\n\n// ─── vocabulary: what a mistyped term could have meant ─────────────────\n// The words that actually occur in the indexed text (latin tokens of four\n// characters or more, lowercased, with counts), built from the text lines\n// on first use and kept while the index is unchanged. A term with no hits\n// is looked up here by edit distance; the caller (or a judge) picks.\n\ninterface Suggestion { term: string; count: number; distance: number }\nlet vocabCache: { builtFrom: string; counts: Map<string, number> } | null = null;\n\nasync function vocabulary(): Promise<Map<string, number>> {\n  let stamp = '';\n  try { const st = await fsp.stat(TEXT_LINES); stamp = `${st.mtimeMs}:${st.size}`; } catch { return new Map(); }\n  if (vocabCache && vocabCache.builtFrom === stamp) return vocabCache.counts;\n  const counts = new Map<string, number>();\n  const lines = createInterface({ input: createReadStream(TEXT_LINES, { encoding: 'utf8', highWaterMark: 1 << 20 }) });\n  for await (const line of lines) {\n    let t: TextLine;\n    try { t = JSON.parse(line) as TextLine; } catch { continue; }\n    for (const body of [t.q, t.a, t.m]) {\n      if (!body) continue;\n      for (const m of body.matchAll(/[A-Za-z][A-Za-z0-9_-]{3,}/g)) { const w = m[0].toLowerCase(); counts.set(w, (counts.get(w) ?? 0) + 1); }\n    }\n  }\n  vocabCache = { builtFrom: stamp, counts };\n  return counts;\n}\n\nfunction editDistance(a: string, b: string, max: number): number {\n  if (Math.abs(a.length - b.length) > max) return max + 1;\n  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);\n  for (let i = 1; i <= a.length; i++) {\n    const cur = [i];\n    let rowMin = i;\n    for (let j = 1; j <= b.length; j++) {\n      const v = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));\n      cur.push(v); if (v < rowMin) rowMin = v;\n    }\n    if (rowMin > max) return max + 1;\n    prev = cur;\n  }\n  return prev[b.length];\n}\n\n/** Terms in the indexed text within a small edit distance of `term`\n *  (one edit for short words, two from six characters on), closest and\n *  most frequent first. Empty for a term that is itself in the text. */\nasync function suggestJson(term: string, k = 8): Promise<{ term: string; known: number; suggestions: Suggestion[] }> {\n  const t = term.toLowerCase().trim();\n  const counts = await vocabulary();\n  const known = counts.get(t) ?? 0;\n  if (!t || t.length < 3) return { term, known, suggestions: [] };\n  const max = t.length >= 6 ? 2 : 1;\n  const out: Suggestion[] = [];\n  for (const [w, count] of counts) {\n    if (w === t) continue;\n    const d = editDistance(t, w, max);\n    if (d <= max) out.push({ term: w, count, distance: d });\n  }\n  out.sort((a, b) => a.distance - b.distance || b.count - a.count);\n  return { term, known, suggestions: out.slice(0, k) };\n}\n\n// ─── topics: what a turn is about, as a judge's typed labels ─────────────\n// A person names their themes (a short table); a System One judge answers,\n// for every turn in the text index, one yes/no per theme; the labels live\n// in <home>/topics.json keyed by source and turn. Recall then reaches a\n// turn by what it is about, not only by the words it shares. Labelling\n// runs here in the host, in the background, and reports progress; the\n// judge's key rides in the call and is not kept.\n\ninterface Topic { id: string; name: string; description: string }\ninterface TopicsFile { version: number; topics: Topic[]; labels: Record<string, Record<string, number>>; labeledAt: Record<string, string>; updatedAt: string }\nconst TOPICS_FILE = path.join(HOME, 'topics.json');\nconst TOPICS_VERSION = 1;\nconst emptyTopics = (): TopicsFile => ({ version: TOPICS_VERSION, topics: [], labels: {}, labeledAt: {}, updatedAt: '' });\n// its own version, apart from the index's: the table outlives reindexing\nconst loadTopics = async (): Promise<TopicsFile> => {\n  try { const v = JSON.parse(await fsp.readFile(TOPICS_FILE, 'utf8')) as TopicsFile; return v.version === TOPICS_VERSION ? { ...emptyTopics(), ...v } : emptyTopics(); } catch { return emptyTopics(); }\n};\nconst turnKey = (k: string, i: number): string => `${k}#${i}`;\n\n/** How the host reaches the judge: the same wire the canvas uses. */\ninterface JudgeCall { url: string; headers: Record<string, string>; model?: string; wrap?: 'cloudflare' }\n/** A slice can halve an emoji into a lone surrogate, which the endpoints reject as invalid Unicode; control characters go too. */\n// eslint-disable-next-line no-control-regex -- the control range is the point\nconst cleanForJudge = (s: string): string => s.replace(/[\\uD800-\\uDBFF](?![\\uDC00-\\uDFFF])|(?<![\\uD800-\\uDBFF])[\\uDC00-\\uDFFF]/g, '').replace(/[\\u0000-\\u0008\\u000B\\u000C\\u000E-\\u001F\\u007F]/g, '');\nasync function systemOne(call: JudgeCall, state: unknown, questions: Record<string, unknown>): Promise<Record<string, { noul?: number; choice?: string; probabilities?: Record<string, number> }>> {\n  const body = call.wrap === 'cloudflare' ? { model: call.model ?? 'typesafe/jev', input: { state, questions } } : { ...(call.model ? { model: call.model } : {}), state, questions };\n  const r = await fetch(call.url, { method: 'POST', headers: { 'Content-Type': 'application/json', ...call.headers }, body: JSON.stringify(body), signal: AbortSignal.timeout(90_000) });\n  const text = await r.text();\n  let j: { answers?: Record<string, { noul?: number }>; result?: { answers?: Record<string, { noul?: number }> }; error?: unknown } = {};\n  try { j = JSON.parse(text); } catch { throw new Error(`judge answered ${r.status} with non-JSON`); }\n  if (!r.ok) throw new Error(typeof j.error === 'string' ? j.error : (j.error as { message?: string })?.message ?? `HTTP ${r.status}`);\n  const answers = (call.wrap === 'cloudflare' ? j.result?.answers : j.answers) ?? {};\n  return answers;\n}\n\ninterface LabelStatus { running: boolean; done: number; total: number; labeled: number; errors: number; startedAt: string | null; finishedAt: string | null; lastError: string | null; stopRequested: boolean }\nconst labelStatus: LabelStatus = { running: false, done: 0, total: 0, labeled: 0, errors: 0, startedAt: null, finishedAt: null, lastError: null, stopRequested: false };\n\n/** The topic table with counts and the labelling job's state. */\nasync function topicsJson(): Promise<{ topics: (Topic & { count: number })[]; labeled: number; turns: number; status: LabelStatus }> {\n  const tf = await loadTopics();\n  const text = await loadText();\n  const turns = Object.values(text.sessions).reduce((n, c) => n + c, 0);\n  const counts = new Map<string, number>();\n  for (const per of Object.values(tf.labels)) for (const [id, p] of Object.entries(per)) if (p >= 0.6) counts.set(id, (counts.get(id) ?? 0) + 1);\n  return { topics: tf.topics.map((t) => ({ ...t, count: counts.get(t.id) ?? 0 })), labeled: Object.keys(tf.labels).length, turns, status: { ...labelStatus } };\n}\n\n/** Replace the topic table; labels of removed topics go, the rest stay. */\nasync function setTopics(topics: { id?: string; name: string; description?: string }[]): Promise<Topic[]> {\n  const tf = await loadTopics();\n  const clean: Topic[] = topics.filter((t) => t.name?.trim()).map((t) => ({ id: (t.id && /^[a-z0-9_-]{1,40}$/.test(t.id) ? t.id : shortHash(t.name.trim().toLowerCase())), name: t.name.trim().slice(0, 60), description: (t.description ?? '').trim().slice(0, 240) }));\n  const keep = new Set(clean.map((t) => t.id));\n  for (const [k, per] of Object.entries(tf.labels)) { for (const id of Object.keys(per)) if (!keep.has(id)) delete per[id]; if (!Object.keys(per).length) { delete tf.labels[k]; delete tf.labeledAt[k]; } }\n  tf.topics = clean; tf.updatedAt = new Date().toISOString();\n  await writePrivate(TOPICS_FILE, tf);\n  return clean;\n}\n\n/** Label every unlabelled turn (or one missing a newer topic) with the judge, in the background. */\nasync function labelStart(call: JudgeCall, opts: { batch?: number; max?: number } = {}): Promise<LabelStatus> {\n  if (labelStatus.running) return { ...labelStatus };\n  const tf = await loadTopics();\n  if (!tf.topics.length) throw new Error('no topics to label with');\n  const batch = Math.max(1, Math.min(16, opts.batch ?? 8));\n  Object.assign(labelStatus, { running: true, done: 0, total: 0, labeled: 0, errors: 0, startedAt: new Date().toISOString(), finishedAt: null, lastError: null, stopRequested: false });\n  void (async () => {\n    try {\n      // what still needs labels: a turn with no label for some current topic.\n      // Two passes, so the index never sits in memory: the keys first (the\n      // newest-indexed `max` of them), then their text as it streams by.\n      const needs = (t: TextLine): boolean => {\n        const have = tf.labels[turnKey(t.k, t.i)];\n        if (have && tf.topics.every((tp) => tp.id in have)) return false;\n        return (t.q?.trim().length ?? 0) + (t.a?.trim().length ?? 0) >= 40;\n      };\n      const open = async (): Promise<ReturnType<typeof createInterface> | null> => { try { await fsp.access(TEXT_LINES); return createInterface({ input: createReadStream(TEXT_LINES, { encoding: 'utf8', highWaterMark: 1 << 20 }) }); } catch { return null; } };\n      const keys: string[] = [];\n      const first = await open();\n      if (first) for await (const line of first) { let t: TextLine; try { t = JSON.parse(line) as TextLine; } catch { continue; } if (needs(t)) keys.push(turnKey(t.k, t.i)); }\n      const chosen = new Set(opts.max ? keys.slice(-opts.max) : keys);\n      const pending: TextLine[] = [];\n      const second = chosen.size ? await open() : null;\n      if (second) for await (const line of second) { let t: TextLine; try { t = JSON.parse(line) as TextLine; } catch { continue; } if (chosen.has(turnKey(t.k, t.i))) pending.push(t); }\n      pending.reverse();\n      labelStatus.total = pending.length;\n      let sinceWrite = 0;\n      for (let at = 0; at < pending.length && !labelStatus.stopRequested; at += batch) {\n        const group = pending.slice(at, at + batch);\n        const state: Record<string, { q: string; a: string }> = {};\n        const questions: Record<string, unknown> = {};\n        group.forEach((t, gi) => {\n          state[`t${gi}`] = { q: cleanForJudge((t.q ?? '').slice(0, 300)), a: cleanForJudge((t.a ?? '').slice(0, 700)) };\n          for (const tp of tf.topics) questions[`t${gi}_${tp.id}`] = { type: 'noul', instructions: `Is the turn \\`t${gi}\\` about the topic \"${tp.name}\"${tp.description ? ` (${tp.description})` : ''}?` };\n        });\n        try {\n          const answers = await systemOne(call, state, questions);\n          group.forEach((t, gi) => {\n            const key = turnKey(t.k, t.i);\n            const per = tf.labels[key] ?? {};\n            for (const tp of tf.topics) { const p = answers[`t${gi}_${tp.id}`]?.noul; if (typeof p === 'number') per[tp.id] = Math.round(p * 100) / 100; }\n            tf.labels[key] = per; tf.labeledAt[key] = new Date().toISOString();\n            labelStatus.labeled++;\n          });\n        } catch (e) {\n          labelStatus.errors++; labelStatus.lastError = e instanceof Error ? e.message : String(e);\n          if (labelStatus.errors >= 5 && labelStatus.labeled === 0) break; // a dead key or endpoint: stop early\n          await new Promise((r) => setTimeout(r, 1500));\n        }\n        labelStatus.done = Math.min(pending.length, at + group.length);\n        sinceWrite += group.length;\n        if (sinceWrite >= 80) { tf.updatedAt = new Date().toISOString(); await writePrivate(TOPICS_FILE, tf); sinceWrite = 0; }\n      }\n      tf.updatedAt = new Date().toISOString();\n      await writePrivate(TOPICS_FILE, tf);\n    } catch (e) {\n      labelStatus.lastError = e instanceof Error ? e.message : String(e);\n    } finally {\n      labelStatus.running = false; labelStatus.finishedAt = new Date().toISOString();\n    }\n  })();\n  return { ...labelStatus };\n}\nfunction labelStop(): LabelStatus { if (labelStatus.running) labelStatus.stopRequested = true; return { ...labelStatus }; }\n\n/** The turns labelled with any of these topics (probability at or above minP), strongest and newest first. */\nasync function byTopicJson(topicIds: string[], opts: { minP?: number; limit?: number } = {}): Promise<{ hits: (FindHitJson & { topics: Record<string, number> })[]; total: number }> {\n  const tf = await loadTopics();\n  const facts = await loadFacts();\n  const minP = opts.minP ?? 0.6;\n  const want = new Set(topicIds);\n  const rows: { key: string; k: string; i: number; score: number; topics: Record<string, number> }[] = [];\n  for (const [key, per] of Object.entries(tf.labels)) {\n    let score = 0; const topics: Record<string, number> = {};\n    for (const [id, p] of Object.entries(per)) if (want.has(id) && p >= minP) { score = Math.max(score, p); topics[id] = p; }\n    if (!score) continue;\n    const hash = key.lastIndexOf('#');\n    rows.push({ key, k: key.slice(0, hash), i: Number(key.slice(hash + 1)), score, topics });\n  }\n  const hits: (FindHitJson & { topics: Record<string, number> })[] = [];\n  for (const r of rows) {\n    const session = facts.sessions[r.k]; const turn = session?.turns.find((t) => t.i === r.i);\n    if (!session || !turn) continue;\n    hits.push({ kind: session.kind === 'memory' ? 'memory' : 'turn', session: session.id, runner: session.runner, title: session.title, cwd: turn.cwd ?? session.cwd, file: session.file, turn: turnNumber(facts, { session, sourceKey: r.k, turn }), at: turn.at ?? null, where: 'Q', snippet: turn.q.slice(0, 200), open: openLink({ session, turn }), topics: r.topics, _score: r.score } as FindHitJson & { topics: Record<string, number>; _score: number });\n  }\n  hits.sort((a, b) => ((b as { _score?: number })._score ?? 0) - ((a as { _score?: number })._score ?? 0) || (b.at ?? '').localeCompare(a.at ?? ''));\n  const total = hits.length;\n  return { hits: hits.slice(0, opts.limit ?? 60).map((h) => { const { _score, ...rest } = h as typeof h & { _score?: number }; void _score; return rest; }), total };\n}\n\n// ─── dossiers: one maintained document per topic ─────────────────────\n// The readable answer to \"what do we know about X\": four sections (what it\n// is, decisions taken, where it stands, what is open), every sentence with\n// its sources, a changelog, and the set of turns it was built from so the\n// next update reads only what is new. Written by the canvas (the chat\n// model lives there); kept here so every client sees the same document.\n\ninterface DossierSentence { text: string; src: string[] }\ninterface DossierSource { session: string; turn: number; runner: string; title: string; at: string | null; open: string; kind: 'turn' | 'memory' }\ninterface Dossier {\n  topicId: string;\n  sections: { what: DossierSentence[]; decisions: DossierSentence[]; now: DossierSentence[]; open: DossierSentence[] };\n  sources: Record<string, DossierSource>;\n  /** session#turn keys the document has read */\n  covered: string[];\n  /** facts the memory judge filed here, waiting to be merged */\n  pending: { id: string; text: string; at: string; from?: string }[];\n  changelog: { at: string; note: string }[];\n  builtAt: string | null;\n  updatedAt: string;\n}\ninterface DossiersFile { version: number; byTopic: Record<string, Dossier> }\nconst DOSSIERS_FILE = path.join(HOME, 'dossiers.json');\nconst DOSSIERS_VERSION = 1;\nconst emptyDossiers = (): DossiersFile => ({ version: DOSSIERS_VERSION, byTopic: {} });\nconst loadDossiers = async (): Promise<DossiersFile> => {\n  try { const v = JSON.parse(await fsp.readFile(DOSSIERS_FILE, 'utf8')) as DossiersFile; return v.version === DOSSIERS_VERSION ? { ...emptyDossiers(), ...v } : emptyDossiers(); } catch { return emptyDossiers(); }\n};\nconst emptyDossier = (topicId: string): Dossier => ({ topicId, sections: { what: [], decisions: [], now: [], open: [] }, sources: {}, covered: [], pending: [], changelog: [], builtAt: null, updatedAt: new Date().toISOString() });\n\ninterface DossierSummary { topicId: string; name: string; built: boolean; builtAt: string | null; updatedAt: string; lead: string; sentences: number; covered: number; pending: number; newTurns: number; labeled: number }\n/** Every topic with its document's state: built or not, how much is new since. */\nasync function dossiersJson(): Promise<DossierSummary[]> {\n  const [tf, df] = await Promise.all([loadTopics(), loadDossiers()]);\n  const out: DossierSummary[] = [];\n  for (const tp of tf.topics) {\n    const d = df.byTopic[tp.id];\n    // keys as the document stores them (session#turn), not the label file's source keys\n    const labeled = (await byTopicJson([tp.id], { limit: 5000 })).hits.map((h) => `${h.session}#${h.turn}`);\n    const covered = new Set(d?.covered ?? []);\n    const s = d?.sections;\n    const sentences = s ? s.what.length + s.decisions.length + s.now.length + s.open.length : 0;\n    out.push({ topicId: tp.id, name: tp.name, built: !!d?.builtAt, builtAt: d?.builtAt ?? null, updatedAt: d?.updatedAt ?? '', lead: s?.what[0]?.text ?? s?.now[0]?.text ?? '', sentences, covered: covered.size, pending: d?.pending.length ?? 0, newTurns: labeled.filter((k) => !covered.has(k)).length, labeled: labeled.length });\n  }\n  return out;\n}\nasync function dossierJson(topicId: string): Promise<Dossier | null> { return (await loadDossiers()).byTopic[topicId] ?? null; }\n\n// Every write to the dossiers file is a read-modify-write of the whole file,\n// and the writers are concurrent by nature: the canvas finishing an update,\n// the memory judge filing a fact in the background, a second host (desktop\n// and plugin share one home). In one process the writes queue behind each\n// other; across processes a lock file of their own serializes them — the\n// index lock is not reused because a refresh is long and a dossier write\n// must wait, not skip (#48).\nconst DOSSIERS_LOCK = path.join(HOME, 'dossiers.lock');\nconst DOSSIERS_LOCK_WAIT_MS = 5_000;\nlet dossierWrites: Promise<unknown> = Promise.resolve();\nasync function withDossiers<T>(fn: (df: DossiersFile) => T): Promise<T> {\n  const run = async (): Promise<T> => {\n    let release: (() => Promise<void>) | null = null;\n    const deadline = Date.now() + DOSSIERS_LOCK_WAIT_MS;\n    while (!(release = await acquireLock(DOSSIERS_LOCK, 30_000)) && Date.now() < deadline) await new Promise((r) => setTimeout(r, 60));\n    // past the deadline the write goes ahead unlocked: losing it would be worse than the race it guards against\n    try {\n      const df = await loadDossiers();\n      const out = fn(df);\n      await writePrivate(DOSSIERS_FILE, df);\n      return out;\n    } finally { await release?.(); }\n  };\n  const p = dossierWrites.then(run, run);\n  dossierWrites = p.catch(() => undefined);\n  return p;\n}\n\n/** Replace a topic's document (the canvas wrote or edited it). An update\n *  that read the inbox names what it read in `consumePending`: those\n *  facts leave, and anything filed while the model was writing stays. */\nasync function setDossier(topicId: string, d: Partial<Dossier> & { consumePending?: string[] }): Promise<Dossier> {\n  return withDossiers((df) => {\n    const cur = df.byTopic[topicId] ?? emptyDossier(topicId);\n    const { consumePending, ...rest } = d;\n    const patch = Object.fromEntries(Object.entries(rest).filter(([, v]) => v !== undefined)) as Partial<Dossier>;\n    const next: Dossier = { ...cur, ...patch, topicId, updatedAt: new Date().toISOString() };\n    if (consumePending) { const read = new Set(consumePending); next.pending = cur.pending.filter((p) => !read.has(p.id)); }\n    df.byTopic[topicId] = next;\n    return next;\n  });\n}\nasync function deleteDossier(topicId: string): Promise<void> { await withDossiers((df) => { delete df.byTopic[topicId]; }); }\n/** File a fact for a later merge (the memory judge's project facts). */\nasync function dossierAddPending(topicId: string, item: { text: string; from?: string }): Promise<Dossier> {\n  return withDossiers((df) => {\n    const cur = df.byTopic[topicId] ?? emptyDossier(topicId);\n    cur.pending.push({ id: shortHash(`${Date.now()}:${cur.pending.length}:${item.text}`), text: item.text.slice(0, 400), at: new Date().toISOString(), ...(item.from ? { from: item.from } : {}) });\n    cur.updatedAt = new Date().toISOString();\n    df.byTopic[topicId] = cur;\n    return cur;\n  });\n}\n/** The topic's labelled turns the document has not read, newest first, with their text — what an update needs. */\nasync function dossierNewTurns(topicId: string, opts: { limit?: number } = {}): Promise<{ hits: (FindHitJson & { topics: Record<string, number> })[]; excerpts: { key: string; q: string; a: string }[]; total: number }> {\n  const d = (await loadDossiers()).byTopic[topicId];\n  const covered = new Set(d?.covered ?? []);\n  const all = await byTopicJson([topicId], { limit: 5000 });\n  const fresh = all.hits.filter((h) => !covered.has(`${h.session}#${h.turn}`));\n  const sorted = fresh.sort((a, b) => (b.at ?? '').localeCompare(a.at ?? '')).slice(0, opts.limit ?? 120);\n  const excerpts: { key: string; q: string; a: string }[] = [];\n  for (const h of sorted) {\n    try { const r = await recallJson(h.session, h.turn); excerpts.push({ key: `${h.session}#${h.turn}`, q: r.question.replace(/\\s+/g, ' ').slice(0, 300), a: r.response.replace(/\\s+/g, ' ').slice(0, 600) }); } catch { /* a turn that fell out of the index */ }\n  }\n  return { hits: sorted, excerpts, total: fresh.length };\n}\n\n/** A sample of the questions people asked, for proposing topics. */\nasync function sampleQuestions(n = 120): Promise<string[]> {\n  const out: string[] = [];\n  let lines: ReturnType<typeof createInterface> | null = null;\n  try { await fsp.access(TEXT_LINES); lines = createInterface({ input: createReadStream(TEXT_LINES, { encoding: 'utf8', highWaterMark: 1 << 20 }) }); } catch { return out; }\n  const all: string[] = [];\n  for await (const line of lines) { let t: TextLine; try { t = JSON.parse(line) as TextLine; } catch { continue; } const q = (t.q ?? '').trim(); if (q.length >= 20 && q.length <= 400) all.push(q); }\n  // spread across the whole history, not the newest slice\n  const step = Math.max(1, Math.floor(all.length / n));\n  for (let i = 0; i < all.length && out.length < n; i += step) out.push(all[i].slice(0, 200));\n  return out;\n}\n\n/** The memory files the index holds, newest first, with their entries' headings. */\nasync function memoriesJson(): Promise<MemoryFileJson[]> {\n  const facts = await ensureFresh();\n  return Object.values(facts.sessions)\n    .filter((x) => x.kind === 'memory')\n    .sort((a, b) => b.mtime - a.mtime)\n    .map((x) => ({ id: x.id, runner: x.runner, file: x.file, title: x.title, cwd: x.cwd, entries: x.turns.length, mtime: x.mtime, headings: x.turns.map((t) => t.q) }));\n}\n\n// ─── mcp ─────────────────────────────────────────────────────────────\n//\n// The same four questions as tools an agent calls itself, over the Model\n// Context Protocol's stdio transport (newline-delimited JSON-RPC 2.0).\n// Read-only by construction: nothing here writes a canvas or a session.\n// stdout carries protocol frames only; every notice goes to stderr.\n\nconst CLI_VERSION = '0.2.2';\nconst MCP_TOOLS = [\n  { name: 'why_check', description: 'Cheap first question before editing a file: does this artifact have any history in local agent sessions? One line; history true/false.', inputSchema: { type: 'object', properties: { path: { type: 'string', description: 'file path (absolute or relative to cwd), URL, or arxiv:<id>' } }, required: ['path'] } },\n  { name: 'why_file', description: 'The turns across local Claude Code, Codex, DeepSeek Harness, Pi and ThoughtDAG sessions that touched a file, URL or paper: when, what changed (Δ, observed), what was asked, what the answer said about it (≈, a candidate explanation, not a verified reason). Each hit carries a deep link.', inputSchema: { type: 'object', properties: { path: { type: 'string' }, include_read: { type: 'boolean', description: 'also list turns that only read it (default false)' }, limit: { type: 'number', description: 'max hits (default 10)' } }, required: ['path'] } },\n  { name: 'find', description: 'Where these exact words were asked (Q), answered (A) or attached (M) across local sessions, canvases and the memories Claude Code and Codex keep for themselves. Exact, case-insensitive match; every hit is a verbatim snippet with a pointer.', inputSchema: { type: 'object', properties: { phrase: { type: 'string' }, in: { type: 'string', enum: ['q', 'a', 'm', 'all'] }, limit: { type: 'number' } }, required: ['phrase'] } },\n  { name: 'recall_turn', description: 'One turn in full — the question, the answer, the tool calls with their diffs — by session id (or prefix) and turn number as shown by why_file.', inputSchema: { type: 'object', properties: { session: { type: 'string' }, turn: { type: 'number' } }, required: ['session', 'turn'] } },\n];\n\nasync function mcpCall(name: string, a: Record<string, unknown>): Promise<string> {\n  if (name === 'why_check') {\n    const facts = await factsForCheck(false);\n    const q = String(a.path ?? '');\n    const { path: file } = await resolveQuery(facts, q, false);\n    return renderCheck(facts, q, file, file ? hitsFor(facts, file, true).hits : [], false).text;\n  }\n  if (name === 'why_file') {\n    const facts = await ensureFresh();\n    const q = String(a.path ?? '');\n    const { path: file, candidates, elsewhere } = await resolveQuery(facts, q, false);\n    if (!file) return candidates.length ? `${candidates.length} files match \"${q}\" — pick one:\\n${candidates.slice(0, 20).map((c) => `  ${c}`).join('\\n')}` : elsewhere ? `no match in this workspace (${elsewhere} elsewhere)` : `no session touched ${q}`;\n    const { hits, readsHidden } = hitsFor(facts, file, a.include_read === true);\n    return renderWhy(facts, file, hits, readsHidden, await loadCache(), Number(a.limit ?? 10) || 10, false);\n  }\n  if (name === 'find') {\n    const facts = await ensureFresh();\n    const scope = (['q', 'a', 'm'] as const).find((x) => x === a.in) ?? 'all';\n    return renderFind(facts, String(a.phrase ?? ''), await findHits(facts, String(a.phrase ?? ''), scope), Number(a.limit ?? 10) || 10, false);\n  }\n  if (name === 'recall_turn') return renderRecall(await ensureFresh(), String(a.session ?? ''), Number(a.turn ?? 0));\n  throw new Error(`unknown tool: ${name}`);\n}\n\n\nexport {\n  HOME,\n  FACT_FILE,\n  CACHE_FILE,\n  TEXT_FILE,\n  TEXT_LINES,\n  LEGACY_FILE,\n  zstdSkipped,\n  eventsOf,\n  LOCK_FILE,\n  loadFacts,\n  loadCache,\n  buildIndex,\n  ensureFresh,\n  artifactsLine,\n  summarize,\n  resolveQuery,\n  hitsFor,\n  when,\n  renderWhy,\n  findHits,\n  renderFind,\n  factsForCheck,\n  renderCheck,\n  renderRecall,\n  recallTurn,\n  findJson,\n  turnsJson,\n  recallJson,\n  memoriesJson,\n  suggestJson,\n  topicsJson,\n  setTopics,\n  labelStart,\n  labelStop,\n  byTopicJson,\n  sampleQuestions,\n  dossiersJson,\n  dossierJson,\n  setDossier,\n  deleteDossier,\n  dossierAddPending,\n  dossierNewTurns,\n  CLI_VERSION,\n  MCP_TOOLS,\n  mcpCall,\n};\n"
